('wk-pets','animals','الحيوانات الأليفة','الحيوانات الأليفة','1f431',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['قطة','كلب','أرنب','دجاجة','خروف','بقرة','حيوانات المزرعة','أليفة']::text[],'الحيوانات الأليفة تعيش قريبًا منا، ونعتني بها ونطعمها.',$j$[{"h": "من هي؟", "x": "القطة تموء، والكلب ينبح، والأرنب يقفز، والدجاجة تبيض.", "t": 1, "ic": "1f436"}, {"h": "ماذا تحتاج؟", "x": "الحيوان الأليف يحتاج إلى طعام وماء ومكان نظيف ودافئ ومن يحبه ويعتني به.", "t": 1, "ic": "1f9fa"}, {"h": "ماذا نأخذ منها؟", "x": "نأخذ الحليب من البقرة، والصوف من الخروف، والبيض من الدجاجة. ويأكل بعضها العشب كالبقرة والخروف، ويأكل بعضها اللحم كالقطة.", "t": 2, "ic": "1f404"}, {"h": "كيف نعتني بها؟", "x": "نعطيها طعامًا مناسبًا لها، ونضع لها ماءً نظيفًا، ونغسل أيدينا بعد أن نلمسها، ونأخذها إلى الطبيب البيطري إذا مرضت.", "t": 2, "ic": "1f9fc"}, {"h": "لماذا سُمّيت أليفة؟", "x": "سُمّيت أليفة لأن الإنسان رعاها منذ آلاف السنين فاعتادت العيش معه. أما الحيوانات البرية فتعيش وحدها في الطبيعة وتجد غذاءها بنفسها. وبعض الحيوانات الأليفة تأكل النباتات فقط (آكلة أعشاب)، وبعضها يأكل اللحم (آكلة لحوم).", "t": 3, "ic": "1f4d6"}]$j$::jsonb,$j$[{"h": "أسنان الأرنب", "x": "أسنان الأرنب الأمامية تظل تنمو طوال حياته، ولهذا يحتاج إلى مضغ العشب والقش.", "ic": "1f430", "t": 2}, {"h": "الصوف", "x": "نجزّ صوف الخروف كما نقصّ الشعر، وهو لا يؤلمه إذا فعلناه بطريقة صحيحة.", "ic": "1f411", "t": 2}, {"h": "المواء", "x": "تموء القطة لتتواصل مع الإنسان، وهي تتواصل مع القطط الأخرى بطرق أخرى كالنظرات وحركة الذيل.", "ic": "1f431", "t": 3}, {"h": "صوت الدجاجة", "x": "الدجاجة تبيض، والكتكوت يخرج من البيضة بعد أن يكتمل نموه داخلها.", "ic": "1f414", "t": 1}]$j$::jsonb,$j$[{"w": "أليف", "m": "يعيش مع الإنسان ويعتاد عليه", "t": 1}, {"w": "مزرعة", "m": "مكان تُربّى فيه الحيوانات وتُزرع فيه النباتات", "t": 2}, {"w": "آكل أعشاب", "m": "حيوان يأكل النباتات فقط", "t": 3}, {"w": "آكل لحوم", "m": "حيوان يأكل اللحم", "t": 3}, {"w": "بيطري", "m": "طبيب يعالج الحيوانات", "t": 2, "ic": "x_doctor"}]$j$::jsonb,$j$[{"k": "match", "p": [["1f431", "قطة"], ["1f436", "كلب"], ["1f430", "أرنب"], ["1f414", "دجاجة"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "ماذا نأخذ من الدجاجة؟", "o": ["الحليب", "البيض", "الصوف"], "a": 1, "ts": [1, 2]}, {"k": "mc", "q": "أي حيوان نأخذ منه الحليب؟", "o": ["البقرة", "الدجاجة", "القطة"], "a": 0, "ts": [1, 2]}, {"k": "tf", "q": "الحيوان الأليف يحتاج إلى ماء نظيف.", "a": true, "ts": [1, 2, 3]}, {"k": "fill", "q": "نأخذ الصوف من ___.", "o": ["الخروف", "القطة", "الأرنب"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "ماذا يفعل الأرنب ليحافظ على أسنانه؟", "o": ["ينام كثيرًا", "يمضغ العشب والقش", "يشرب الحليب"], "a": 1, "ts": [3]}, {"k": "sort", "g": ["يأكل العشب", "يأكل اللحم"], "i": [["البقرة", 0, "1f404"], ["الخروف", 0, "1f411"], ["القطة", 1, "1f431"]], "ts": [2, 3]}]$j$::jsonb,array['wk-wild','wk-sea']::text[],$j$[{"type": "stories", "q": ["My Pets"]}, {"type": "cards", "cat": "animals", "sub": "أليفة", "label": "بطاقات الحيوانات الأليفة"}, {"type": "activities", "q": ["الحيوانات", "حيوانات المزرعة"]}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',10),
('wk-wild','animals','الحيوانات البرية','الحيوانات البرية','1f981',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['أسد','فيل','زرافة','نمر','دب','غابة','سافانا','برية']::text[],'الحيوانات البرية تعيش في الطبيعة وتجد طعامها بنفسها.',$j$[{"h": "من هي؟", "x": "الأسد يزأر، والفيل كبير، والزرافة طويلة، والدب قوي.", "t": 1, "ic": "1f981"}, {"h": "أين تعيش؟", "x": "تعيش في الغابة وفي الأرض العشبية الواسعة وفي الجبال.", "t": 1, "ic": "1f333"}, {"h": "ماذا تأكل؟", "x": "الفيل والزرافة والحمار الوحشي تأكل النباتات. والأسد والنمر يأكلان اللحم. والدب يأكل النباتات واللحم معًا.", "t": 2, "ic": "1f418"}, {"h": "كيف تساعدها أجسامها؟", "x": "رقبة الزرافة الطويلة تصل بها إلى أوراق الأشجار العالية. وخرطوم الفيل يُمسك به الطعام ويشرب به ويشمّ. وفراء الدب السميك يدفّئه.", "t": 2, "ic": "1f992"}, {"h": "بيوتها وعلاقتها بالإنسان", "x": "لكل حيوان بيئة تناسبه تسمّى موطنًا. وعندما تُقطع الغابات أو يقلّ الطعام والماء تتعرض بعض الحيوانات للخطر. لذلك تُنشأ المحميات لحمايتها.", "t": 3, "ic": "1f333"}]$j$::jsonb,$j$[{"h": "أكبر حيوان بري", "x": "الفيل الأفريقي أكبر حيوان يعيش على اليابسة.", "ic": "1f418", "t": 1}, {"h": "أطول حيوان", "x": "الزرافة أطول حيوان على وجه الأرض.", "ic": "1f992", "t": 1}, {"h": "الأسود", "x": "تعيش الأسود في مجموعات تسمّى قطعانًا، وتتعاون إناثها في الصيد.", "ic": "1f981", "t": 3}, {"h": "الفيل", "x": "يستعمل الفيل خرطومه ليشرب ويشمّ ويلتقط الأشياء.", "ic": "1f418", "t": 2}]$j$::jsonb,$j$[{"w": "بري", "m": "يعيش في الطبيعة بعيدًا عن البيوت", "t": 1}, {"w": "غابة", "m": "مكان فيه أشجار كثيرة", "t": 1, "ic": "1f333"}, {"w": "موطن", "m": "المكان الذي يعيش فيه الحيوان", "t": 2}, {"w": "محمية", "m": "مكان تُحمى فيه الحيوانات والنباتات", "t": 3}, {"w": "آكل لحوم", "m": "حيوان يأكل اللحم", "t": 2}]$j$::jsonb,$j$[{"k": "match", "p": [["1f981", "أسد"], ["1f418", "فيل"], ["1f992", "زرافة"], ["1f43b", "دب"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "أي حيوان هو الأطول؟", "o": ["الفيل", "الزرافة", "الأسد"], "a": 1, "ts": [1, 2]}, {"k": "tf", "q": "الفيل أكبر حيوان على اليابسة.", "a": true, "ts": [1, 2, 3]}, {"k": "fill", "q": "يعيش الأسد في ___ بري.", "o": ["موطن", "بيت", "قفص"], "a": 0, "ts": [3]}, {"k": "mc", "q": "لماذا تُنشأ المحميات؟", "o": ["لتبيع الحيوانات", "لحماية الحيوانات وموطنها", "لتبني المدن"], "a": 1, "ts": [3]}, {"k": "sort", "g": ["يأكل النباتات", "يأكل اللحم"], "i": [["الفيل", 0, "1f418"], ["الزرافة", 0, "1f992"], ["الأسد", 1, "1f981"], ["النمر", 1, "1f42f"]], "ts": [2, 3]}, {"k": "odd", "i": [["أسد", "1f981"], ["نمر", "1f42f"], ["سمكة", "1f41f"]], "a": 2, "why": "السمكة تعيش في الماء، أما الأسد والنمر فيعيشان على اليابسة.", "ts": [2, 3]}]$j$::jsonb,array['wk-pets','wk-deserts-forests']::text[],$j$[{"type": "cards", "cat": "animals", "sub": "برية", "label": "بطاقات الحيوانات البرية"}, {"type": "stories", "q": ["الفيل", "الغابة"]}, {"type": "activities", "q": ["الحيوانات"]}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',20),
('wk-sea','animals','الحيوانات البحرية','الحيوانات البحرية','1f40b',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['سمكة','حوت','دلفين','أخطبوط','سلحفاة','سرطان','بحر','محيط']::text[],'في البحر والمحيط تعيش حيوانات كثيرة، بعضها صغير وبعضها كبير جدًا.',$j$[{"h": "من يسبح في البحر؟", "x": "السمكة والحوت والدلفين والأخطبوط والسلحفاة والسرطان.", "t": 1, "ic": "1f41f"}, {"h": "كيف تتنفس؟", "x": "السمكة تتنفس بأعضاء تسمّى الخياشيم. أما الحوت والدلفين فيصعدان إلى سطح الماء ليتنفسا الهواء.", "t": 2, "ic": "1f42c"}, {"h": "أحجام وأشكال مختلفة", "x": "السلحفاة لها درع صلب يحميها. والأخطبوط له ثماني أذرع. والسرطان له مخالب يمسك بها طعامه.", "t": 2, "ic": "1f419"}, {"h": "الثدييات البحرية", "x": "الحوت والدلفين ليسا سمكتين، بل ثدييان: يتنفسان الهواء، وترضع الأم صغيرها الحليب. أما السمك فيتنفس تحت الماء بالخياشيم ويبيض.", "t": 3, "ic": "1f40b"}, {"h": "حماية البحر", "x": "يضرّ البلاستيك والنفايات بالسلاحف والأسماك، لذلك نحافظ على نظافة الشواطئ والبحر.", "t": 3, "ic": "1f422"}]$j$::jsonb,$j$[{"h": "أكبر حيوان", "x": "الحوت الأزرق أكبر حيوان عُرف على الأرض حتى اليوم.", "ic": "1f40b", "t": 1}, {"h": "الأخطبوط", "x": "للأخطبوط ثلاثة قلوب وثماني أذرع.", "ic": "1f419", "t": 3}, {"h": "الدلفين", "x": "الدلفين حيوان ثديي يتنفس الهواء، وليس سمكة.", "ic": "1f42c", "t": 2}, {"h": "سلاحف عُمان", "x": "تضع السلاحف الخضراء بيضها على شواطئ في سلطنة عُمان، ومنها شاطئ رأس الجِنز.", "ic": "1f422", "t": 3}]$j$::jsonb,$j$[{"w": "خياشيم", "m": "أعضاء تتنفس بها الأسماك تحت الماء", "t": 2}, {"w": "ثديي", "m": "حيوان يرضع صغيره الحليب", "t": 3}, {"w": "محيط", "m": "مساحة ماء مالح واسعة جدًا", "t": 2}, {"w": "درع", "m": "غطاء صلب يحمي السلحفاة", "t": 2}, {"w": "شاطئ", "m": "حافة اليابسة عند البحر", "t": 1}]$j$::jsonb,$j$[{"k": "match", "p": [["1f41f", "سمكة"], ["1f40b", "حوت"], ["1f419", "أخطبوط"], ["1f980", "سرطان"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "أين تعيش السمكة؟", "o": ["في الماء", "في الغابة", "في الصحراء"], "a": 0, "ts": [1, 2]}, {"k": "tf", "q": "الدلفين سمكة.", "a": false, "ts": [2, 3]}, {"k": "mc", "q": "كم ذراعًا للأخطبوط؟", "o": ["أربع", "ست", "ثمانٍ"], "a": 2, "ts": [2, 3]}, {"k": "fill", "q": "تتنفس السمكة بـ ___.", "o": ["الخياشيم", "الرئتين فقط", "الأذنين"], "a": 0, "ts": [3]}, {"k": "sort", "g": ["حيوان بحري", "حيوان بري"], "i": [["الحوت", 0, "1f40b"], ["الأخطبوط", 0, "1f419"], ["الأسد", 1, "1f981"], ["الفيل", 1, "1f418"]], "ts": [1, 2, 3]}]$j$::jsonb,array['wk-continents-oceans','wk-water']::text[],$j$[{"type": "cards", "cat": "animals", "sub": "بحرية", "label": "بطاقات الحيوانات البحرية"}, {"type": "stories", "q": ["البطة", "البطريق"]}, {"type": "activities", "q": ["برّ وماء"]}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',30),
('wk-insects','animals','الحشرات','الحشرات','1f98b',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['نحلة','فراشة','دعسوقة','نمل','حشرة','عسل']::text[],'الحشرات حيوانات صغيرة، وهي مهمة جدًا لحياة النباتات والعسل.',$j$[{"h": "من هي؟", "x": "النحلة والفراشة والدعسوقة والنملة حشرات صغيرة.", "t": 1, "ic": "1f41d"}, {"h": "ماذا تفعل؟", "x": "النحلة تصنع العسل. والفراشة تطير بين الأزهار. والنملة تحمل الطعام إلى بيتها.", "t": 1, "ic": "1f98b"}, {"h": "جسم الحشرة", "x": "للحشرة ستة أرجل، وجسمها ثلاثة أجزاء: الرأس والصدر والبطن. ولها قرنا استشعار على رأسها، وأغلبها له أجنحة.", "t": 2, "ic": "x_ladybug"}, {"h": "كيف تصنع النحلة العسل؟", "x": "تجمع النحلة رحيق الأزهار، وتعود به إلى الخلية، فيتحول إلى عسل. وتنقل النحلة غبار الطلع من زهرة إلى أخرى، وهذا يساعد النباتات على إنتاج الثمار.", "t": 2, "ic": "1f41d"}, {"h": "رحلة الفراشة", "x": "تمرّ الفراشة بأربع مراحل: بيضة، ثم يرقة (دودة صغيرة)، ثم شرنقة، ثم فراشة بالغة. ويسمّى هذا التحول الكامل.", "t": 3, "ic": "x_caterpillar"}, {"h": "العنكبوت ليس حشرة", "x": "للعنكبوت ثمانية أرجل وجسمه جزءان، لذلك لا يُعدّ حشرة.", "t": 3, "ic": "1f577"}]$j$::jsonb,$j$[{"h": "ست أرجل", "x": "كل الحشرات لها ست أرجل.", "ic": "1f41d", "t": 1}, {"h": "نحلة وغبار الطلع", "x": "تنقل النحلة غبار الطلع بين الأزهار فتساعد النباتات على إنتاج الثمار.", "ic": "1f41d", "t": 2}, {"h": "التحول", "x": "الفراشة تبدأ حياتها بيضة ثم يرقة ثم شرنقة ثم فراشة.", "ic": "x_chrysalis", "t": 2}, {"h": "النمل", "x": "يعيش النمل في مجتمعات منظمة ويتعاون أفرادها في حمل الطعام وبناء البيت.", "ic": "1f44f", "t": 3}]$j$::jsonb,$j$[{"w": "خلية", "m": "بيت النحل", "t": 1}, {"w": "رحيق", "m": "سائل حلو في الأزهار تجمعه النحلة", "t": 2}, {"w": "يرقة", "m": "مرحلة صغيرة تشبه الدودة قبل الشرنقة", "t": 3, "ic": "x_caterpillar"}, {"w": "شرنقة", "m": "غلاف تتحول داخله اليرقة إلى فراشة", "t": 3, "ic": "x_chrysalis"}, {"w": "قرن استشعار", "m": "عضو على رأس الحشرة تحس به", "t": 3}]$j$::jsonb,$j$[{"k": "match", "p": [["1f41d", "نحلة"], ["1f98b", "فراشة"], ["x_ladybug", "دعسوقة"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "أي حشرة تصنع العسل؟", "o": ["الفراشة", "النحلة", "الدعسوقة"], "a": 1, "ts": [1, 2]}, {"k": "tf", "q": "للحشرة ستة أرجل.", "a": true, "ts": [2, 3]}, {"k": "mc", "q": "ما أول مرحلة في حياة الفراشة؟", "o": ["شرنقة", "بيضة", "فراشة"], "a": 1, "ts": [2, 3]}, {"k": "fill", "q": "تجمع النحلة ___ الأزهار.", "o": ["رحيق", "ماء البحر", "أوراق"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "لماذا لا يُعدّ العنكبوت حشرة؟", "o": ["لأن له ثمانية أرجل", "لأنه كبير", "لأنه يطير"], "a": 0, "ts": [3]}, {"k": "match", "p": [["x_buteggs", "بيضة"], ["x_caterpillar", "يرقة"], ["x_chrysalis", "شرنقة"], ["1f98b", "فراشة"]], "ts": [3]}]$j$::jsonb,array['wk-plant-parts','wk-pets']::text[],$j$[{"type": "cards", "cat": "animals", "sub": "حشرات", "label": "بطاقات الحشرات"}, {"type": "stories", "q": ["النحلة"]}, {"type": "activities", "q": ["الضفدع"]}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',40),
('wk-plant-parts','plants','أجزاء النبات','أجزاء النبات','1f331',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['جذر','ساق','ورقة','زهرة','ثمرة','بذرة','نبات']::text[],'النبات له أجزاء، ولكل جزء عمل مهم.',$j$[{"h": "أجزاء النبات", "x": "للنبات جذر في التربة، وساق، وأوراق، وزهرة.", "t": 1, "ic": "x_plant"}, {"h": "ماذا يفعل كل جزء؟", "x": "الجذر يمسك النبات في التربة ويأخذ الماء. الساق تحمل النبات وتوصل الماء إلى الأوراق. الأوراق تصنع غذاء النبات. الزهرة تتحول إلى ثمرة فيها بذور.", "t": 2, "ic": "1f33f"}, {"h": "من البذرة إلى النبتة", "x": "تُزرع البذرة في التربة وتُسقى، فتنبت وتخرج منها نبتة صغيرة، ثم تكبر.", "t": 1, "ic": "x_seed"}, {"h": "صنع الغذاء", "x": "تأخذ الأوراق ضوء الشمس والماء وغاز ثاني أكسيد الكربون من الهواء، وتصنع بها غذاءها، وتُطلق الأكسجين الذي نتنفسه. تسمّى هذه العملية البناء الضوئي.", "t": 3, "ic": "x_leaf"}]$j$::jsonb,$j$[{"h": "الجذور", "x": "جذور الأشجار قد تمتد في الأرض وتثبّتها، وبعضها يمتد بعيدًا بحثًا عن الماء.", "ic": "x_soil", "t": 3}, {"h": "الأكسجين", "x": "النباتات تطلق الأكسجين الذي نتنفسه.", "ic": "1f333", "t": 2}, {"h": "عباد الشمس", "x": "تميل أزهار عباد الشمس الصغيرة نحو الشمس.", "ic": "1f33b", "t": 1}, {"h": "البذرة", "x": "داخل البذرة نبتة صغيرة جدًا تنتظر الماء والدفء لتنمو.", "ic": "x_seed", "t": 2}]$j$::jsonb,$j$[{"w": "جذر", "m": "جزء النبات الذي يكون تحت التربة", "t": 1}, {"w": "ساق", "m": "جزء يحمل الأوراق والأزهار", "t": 1}, {"w": "بذرة", "m": "حبة تنبت منها نبتة جديدة", "t": 1, "ic": "x_seed"}, {"w": "تربة", "m": "الأرض التي تنمو فيها النباتات", "t": 2, "ic": "x_soil"}, {"w": "البناء الضوئي", "m": "صنع النبات غذاءه بضوء الشمس", "t": 3}]$j$::jsonb,$j$[{"k": "match", "p": [["x_seed", "بذرة"], ["x_leaf", "ورقة"], ["1f337", "زهرة"], ["x_soil", "تربة"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "أي جزء يأخذ الماء من التربة؟", "o": ["الجذر", "الزهرة", "الورقة"], "a": 0, "ts": [1, 2]}, {"k": "tf", "q": "الأوراق تصنع غذاء النبات.", "a": true, "ts": [2, 3]}, {"k": "fill", "q": "تتحول الزهرة إلى ___ فيها بذور.", "o": ["ثمرة", "جذر", "حجر"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "أي غاز تطلقه النباتات ونحتاج إليه؟", "o": ["الأكسجين", "الدخان", "الغبار"], "a": 0, "ts": [3]}, {"k": "mc", "q": "ما أول ما يخرج من البذرة عندما تنبت؟", "o": ["جذر صغير", "ثمرة", "زهرة كبيرة"], "a": 0, "ts": [3]}]$j$::jsonb,array['wk-plant-needs','wk-fruit-veg']::text[],$j$[{"type": "activities", "q": ["بذرة", "النبتة"]}, {"type": "stories", "q": ["بُذَيرة"]}, {"type": "cards", "cat": "vocab", "sub": "الطبيعة", "label": "بطاقات الطبيعة"}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',50),
('wk-plant-needs','plants','احتياجات النبات للنمو','ماذا يحتاج النبات ليكبر؟','x_wcan',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['ماء','ضوء','هواء','تربة','ري','نمو النبات']::text[],'النبات كائن حي يحتاج إلى أشياء ليعيش ويكبر.',$j$[{"h": "ماذا يحتاج؟", "x": "يحتاج النبات إلى ماء وضوء الشمس وهواء وتربة.", "t": 1, "ic": "x_wcan"}, {"h": "الماء والشمس", "x": "نسقي النبات بالماء، ونضعه في مكان يصله فيه الضوء. إذا غاب الماء أو الضوء ذبل النبات.", "t": 1, "ic": "2600"}, {"h": "التربة والهواء", "x": "تحتوي التربة على مواد يحتاجها النبات للنمو. والهواء يحتوي على غاز تستعمله الأوراق في صنع الغذاء.", "t": 2, "ic": "x_soil"}, {"h": "تجربة بسيطة", "x": "ضع نبتتين متشابهتين: الأولى في الضوء والثانية في مكان مظلم لعدة أيام وأسقِهما بالقدر نفسه، ثم لاحظ الفرق. الأولى ستبقى خضراء والثانية ستضعف وتصفرّ.", "t": 3, "ic": "1f52c"}, {"h": "بيئات مختلفة", "x": "بعض النباتات كالصبّار تعيش في أماكن قليلة المطر لأنها تخزّن الماء في ساقها، وبعضها يحتاج إلى ماء كثير.", "t": 3, "ic": "1f331"}]$j$::jsonb,$j$[{"h": "بلا ماء", "x": "النبات الذي لا يأخذ ماءً يذبل بعد وقت.", "ic": "x_wcan", "t": 1}, {"h": "الصبّار", "x": "يخزّن الصبّار الماء في ساقه ليتحمل الجفاف.", "ic": "1f331", "t": 3}, {"h": "نبتة في الظلام", "x": "النبتة التي تُترك في الظلام تصفرّ وتضعف.", "ic": "1f331", "t": 2}, {"h": "التسميد", "x": "يضيف المزارعون السماد للتربة ليعطي النبات مواد يحتاجها.", "ic": "x_farmer", "t": 3}]$j$::jsonb,$j$[{"w": "ري", "m": "إعطاء النبات الماء", "t": 1, "ic": "x_wcan"}, {"w": "ذبل", "m": "ضعف النبات وجفّ", "t": 1}, {"w": "سماد", "m": "مادة تُضاف إلى التربة لتغذّي النبات", "t": 3}, {"w": "جفاف", "m": "قلة الماء", "t": 3}, {"w": "نبتة", "m": "نبات صغير", "t": 1, "ic": "1f331"}]$j$::jsonb,$j$[{"k": "mc", "q": "ماذا يحتاج النبات ليعيش؟", "o": ["ماء وضوء", "حلوى", "ألعاب"], "a": 0, "ts": [1, 2]}, {"k": "match", "p": [["x_wcan", "ماء"], ["2600", "ضوء الشمس"], ["x_soil", "تربة"], ["1f4a8", "هواء"]], "ts": [1, 2, 3]}, {"k": "tf", "q": "النبات ينمو جيدًا في الظلام الدائم.", "a": false, "ts": [2, 3]}, {"k": "fill", "q": "نسقي النبات بـ ___.", "o": ["الماء", "الحليب", "العصير"], "a": 0, "ts": [1, 2]}, {"k": "mc", "q": "لماذا لا يذبل الصبّار بسرعة؟", "o": ["يخزّن الماء في ساقه", "يعيش في الماء", "لا يحتاج إلى شيء"], "a": 0, "ts": [3]}, {"k": "sort", "g": ["يحتاجه النبات", "لا يحتاجه النبات"], "i": [["الماء", 0, "x_wcan"], ["ضوء الشمس", 0, "2600"], ["الحلوى", 1, "1f36c"], ["الحذاء", 1, "x_shoes"]], "ts": [1, 2, 3]}]$j$::jsonb,array['wk-plant-parts','wk-water']::text[],$j$[{"type": "activities", "q": ["بذرة", "النبتة"]}, {"type": "stories", "q": ["بُذَيرة"]}, {"type": "media", "q": ["النبات"]}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',60),
('wk-fruit-veg','plants','الفواكه والخضروات','الفواكه والخضروات','1f34e',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['تفاح','موز','عنب','جزر','خيار','طماطم','تمر','نخلة','فواكه','خضروات']::text[],'الفواكه والخضروات من النباتات، وهي طعام لذيذ ومفيد لأجسامنا.',$j$[{"h": "أمثلة", "x": "التفاح والموز والعنب والبرتقال فواكه. والجزر والخيار والباذنجان خضروات.", "t": 1, "ic": "1f34e"}, {"h": "لماذا نأكلها؟", "x": "تعطينا الفواكه والخضروات الفيتامينات والماء، وتجعل أجسامنا قوية، ونحرص أن نغسلها قبل الأكل.", "t": 1, "ic": "1f955"}, {"h": "من أي جزء من النبات؟", "x": "الثمرة تنمو من الزهرة وفيها بذور، مثل التفاح والعنب. وبعض الخضروات جذور كالجزر، وبعضها أوراق كالخس، وبعضها ثمار كالخيار.", "t": 2, "ic": "1f33f"}, {"h": "أطعمة متنوعة", "x": "تناول ألوانًا متنوعة من الفواكه والخضروات كل يوم، فلكل لون فوائد مختلفة. وتحتوي أيضًا على الألياف التي تساعد الجهاز الهضمي.", "t": 3, "ic": "1f347"}, {"h": "النخلة وثمر التمر", "x": "النخلة شجرة مهمة في سلطنة عُمان وفي بلدان كثيرة في المنطقة، وتعطينا التمر وهو غذاء مفيد.", "t": 3, "ic": "1f334"}]$j$::jsonb,$j$[{"h": "العنب", "x": "العنب فاكهة ثمرتها صغيرة تنمو في عناقيد.", "ic": "1f347", "t": 1}, {"h": "الجزر", "x": "الجزر الذي نأكله هو جذر النبات.", "ic": "1f955", "t": 2}, {"h": "الطماطم", "x": "الطماطم من الناحية العلمية ثمرة لأن فيها بذورًا، ونعاملها في الطبخ كخضار.", "ic": "1f346", "t": 3}, {"h": "الماء", "x": "تحتوي كثير من الفواكه على قدر كبير من الماء، مثل البطيخ.", "ic": "1f349", "t": 2}]$j$::jsonb,$j$[{"w": "فيتامين", "m": "مادة مفيدة تحتاجها أجسامنا لتكون قوية", "t": 2}, {"w": "عنقود", "m": "مجموعة حبات تنمو معًا مثل العنب", "t": 2}, {"w": "ألياف", "m": "مواد في الخضروات تساعد الهضم", "t": 3}, {"w": "ثمرة", "m": "جزء من النبات فيه بذور", "t": 2}, {"w": "غسل", "m": "تنظيف الطعام بالماء", "t": 1, "ic": "1f9fc"}]$j$::jsonb,$j$[{"k": "match", "p": [["1f34e", "تفاح"], ["1f34c", "موز"], ["1f955", "جزر"], ["1f347", "عنب"]], "ts": [1, 2, 3]}, {"k": "sort", "g": ["فاكهة", "خضار"], "i": [["التفاح", 0, "1f34e"], ["الموز", 0, "1f34c"], ["الجزر", 1, "1f955"], ["الخيار", 1, "1f952"]], "ts": [1, 2, 3]}, {"k": "tf", "q": "نغسل الفاكهة قبل أن نأكلها.", "a": true, "ts": [1, 2, 3]}, {"k": "fill", "q": "الجزر الذي نأكله هو ___ النبات.", "o": ["جذر", "زهرة", "بذرة"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "لماذا نأكل الفواكه والخضروات؟", "o": ["لتبقى أجسامنا قوية", "لنلعب بها", "لتغيّر لوننا"], "a": 0, "ts": [1, 2]}, {"k": "odd", "i": [["تفاح", "1f34e"], ["موز", "1f34c"], ["حذاء", "x_shoes"]], "a": 2, "why": "التفاح والموز طعام، أما الحذاء فلا يُؤكل.", "ts": [2, 3]}]$j$::jsonb,array['wk-plant-parts','wk-healthy-habits']::text[],$j$[{"type": "cards", "cat": "food", "sub": "فواكه", "label": "بطاقات الفواكه"}, {"type": "cards", "cat": "food", "sub": "خضروات", "label": "بطاقات الخضروات"}, {"type": "stories", "q": ["Fruit", "سلة"]}, {"type": "activities", "q": ["الفواكه"]}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',70),
('wk-senses','body','الحواس الخمس','الحواس الخمس','x_eye',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['حواس','عين','أذن','أنف','لسان','جلد','بصر','سمع','شم','تذوق','لمس']::text[],'نتعرف على العالم من حولنا بحواسنا الخمس.',$j$[{"h": "الحواس الخمس", "x": "نرى بعيوننا، ونسمع بآذاننا، ونشمّ بأنوفنا، ونتذوق بألسنتنا، ونلمس بجلدنا وأيدينا.", "t": 1, "ic": "x_eye"}, {"h": "ماذا نفعل بها؟", "x": "نرى الألوان، ونسمع الأصوات، ونشمّ رائحة الزهور، ونتذوق الطعام الحلو والمالح، ونحسّ إن كان الشيء ناعمًا أو خشنًا أو ساخنًا أو باردًا.", "t": 1, "ic": "1f604"}, {"h": "كيف تعمل؟", "x": "ترسل الحواس إشارات إلى الدماغ، والدماغ يفهمها ويقرر ماذا نفعل. فإذا لمست شيئًا ساخنًا يعرف الدماغ بسرعة أنك يجب أن تسحب يدك.", "t": 2, "ic": "1f9e0"}, {"h": "مذاقات اللسان", "x": "يتعرف اللسان على طعوم منها الحلو والحامض والمالح والمرّ. ويساعد الأنف على تمييز الطعم، لذلك لا نحسّ بالطعم جيدًا عندما نُصاب بالزكام.", "t": 3, "ic": "x_mouth"}, {"h": "نحافظ على حواسنا", "x": "نحمي العين من الضوء القوي، ولا ندخل أشياء في الأذن، ولا نرفع صوت السماعات، ونزور الطبيب إذا شعرنا بمشكلة.", "t": 3, "ic": "x_ear"}]$j$::jsonb,$j$[{"h": "الجلد", "x": "الجلد أكبر عضو في جسم الإنسان، ونلمس به.", "ic": "x_hand", "t": 2}, {"h": "الأذن والتوازن", "x": "الأذن تساعدنا على السمع وعلى الحفاظ على توازن الجسم.", "ic": "x_ear", "t": 3}, {"h": "الرائحة", "x": "الأنف يميّز روائح كثيرة مختلفة.", "ic": "x_nose", "t": 1}, {"h": "العين", "x": "نغلق أعيننا ونفتحها مرات كثيرة يوميًا فيتجدد ترطيبها وتنظيفها.", "ic": "x_eye", "t": 2}]$j$::jsonb,$j$[{"w": "حاسة", "m": "قدرة تساعدنا على معرفة ما حولنا", "t": 1}, {"w": "بصر", "m": "الرؤية بالعين", "t": 2}, {"w": "سمع", "m": "الإحساس بالأصوات بالأذن", "t": 2}, {"w": "ملمس", "m": "شكل سطح الشيء: ناعم أو خشن", "t": 2}, {"w": "توازن", "m": "قدرة الجسم على أن يبقى ثابتًا لا يسقط", "t": 3}]$j$::jsonb,$j$[{"k": "match", "p": [["x_eye", "عين"], ["x_ear", "أذن"], ["x_nose", "أنف"], ["x_mouth", "لسان"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "بماذا نشمّ الرائحة؟", "o": ["بالأنف", "بالقدم", "بالأذن"], "a": 0, "ts": [1, 2]}, {"k": "mc", "q": "بماذا نسمع؟", "o": ["بالعين", "بالأذن", "باليد"], "a": 1, "ts": [1, 2]}, {"k": "tf", "q": "نلمس بالجلد.", "a": true, "ts": [2, 3]}, {"k": "fill", "q": "ترسل الحواس إشارات إلى ___.", "o": ["الدماغ", "القدم", "الحذاء"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "ما أكبر عضو في جسم الإنسان؟", "o": ["الجلد", "القلب", "الأذن"], "a": 0, "ts": [3]}, {"k": "sort", "g": ["أراه بعيني", "أسمعه بأذني"], "i": [["قوس قزح", 0, "1f308"], ["الشمس", 0, "2600"], ["الجرس", 1, "i_bell"], ["الطبل", 1, "1f941"]], "ts": [1, 2, 3]}]$j$::jsonb,array['wk-body-parts','wk-sound','wk-light-shadow']::text[],$j$[{"type": "activities", "q": ["حواسّي"]}, {"type": "cards", "cat": "vocab", "sub": "أجزاء الجسم", "label": "بطاقات أجزاء الجسم"}, {"type": "stories", "q": ["My Body"]}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',80),
('wk-body-parts','body','أجزاء الجسم','أجزاء جسمي وأعضاؤه','1f9e0',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['جسم','قلب','رئة','دماغ','عظام','عضلات','معدة','يد','قدم','رأس']::text[],'جسمك له أجزاء كثيرة، وكل جزء له عمل.',$j$[{"h": "أجزاء الجسم", "x": "لي رأس وذراعان ويدان ورجلان وقدمان.", "t": 1, "ic": "x_hand"}, {"h": "ما عمل الأيدي والأقدام؟", "x": "نمسك الأشياء بأيدينا، ونمشي ونجري بأقدامنا، ونفكر بدماغنا داخل الرأس.", "t": 1, "ic": "x_foot"}, {"h": "أعضاء داخل الجسم", "x": "القلب يضخ الدم في الجسم. الرئتان تساعدان على التنفس. المعدة تهضم الطعام. الدماغ يفكر ويتحكم في الجسم.", "t": 2, "ic": "1f9e0"}, {"h": "العظام والعضلات", "x": "العظام تعطي الجسم شكله وتحمي أعضاءه، والعضلات تتقلص وترتخي لنتحرك. ويعمل العظم والعضل معًا.", "t": 2, "ic": "1f9b4"}, {"h": "أجهزة الجسم", "x": "تعمل الأعضاء معًا في أجهزة: جهاز التنفس (الرئتان)، وجهاز الدوران (القلب والدم)، والجهاز الهضمي (المعدة والأمعاء)، والجهاز العصبي (الدماغ والأعصاب).", "t": 3, "ic": "x_stetho"}]$j$::jsonb,$j$[{"h": "القلب", "x": "القلب عضلة حجمها قريب من قبضة يدك، ولا يتوقف عن النبض.", "ic": "x_stetho", "t": 2}, {"h": "العظام", "x": "في جسم الإنسان البالغ 206 عظام، وللطفل عظام أكثر تلتحم مع الوقت.", "ic": "1f9b4", "t": 3}, {"h": "الدماغ", "x": "الدماغ يتحكم في جسمك ويساعدك على التفكير والتذكر.", "ic": "1f9e0", "t": 1}, {"h": "الأسنان", "x": "الأسنان تقطع الطعام وتمضغه، لذلك نحافظ على نظافتها.", "ic": "1f9b7", "t": 1}]$j$::jsonb,$j$[{"w": "عضو", "m": "جزء من الجسم له عمل", "t": 2}, {"w": "قلب", "m": "عضو يضخ الدم في الجسم", "t": 1}, {"w": "رئتان", "m": "عضوان للتنفس", "t": 2}, {"w": "هيكل عظمي", "m": "مجموعة عظام الجسم", "t": 3, "ic": "1f9b4"}, {"w": "هضم", "m": "تحويل الطعام في المعدة ليستفيد منه الجسم", "t": 3}]$j$::jsonb,$j$[{"k": "match", "p": [["x_hand", "يد"], ["x_foot", "قدم"], ["1f9e0", "دماغ"], ["1f9b7", "سن"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "ما الذي نمشي به؟", "o": ["الأقدام", "الأيدي", "الأذنان"], "a": 0, "ts": [1, 2]}, {"k": "mc", "q": "أي عضو يفكر ويتحكم في الجسم؟", "o": ["الدماغ", "المعدة", "القدم"], "a": 0, "ts": [1, 2]}, {"k": "tf", "q": "القلب يضخ الدم في الجسم.", "a": true, "ts": [2, 3]}, {"k": "fill", "q": "تهضم ___ الطعام.", "o": ["المعدة", "العين", "الأذن"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "كم عظمة في جسم الإنسان البالغ؟", "o": ["206", "50", "1000"], "a": 0, "ts": [3]}, {"k": "mc", "q": "ما وظيفة الرئتين؟", "o": ["التنفس", "الرؤية", "الكتابة"], "a": 0, "ts": [3]}]$j$::jsonb,array['wk-senses','wk-healthy-habits']::text[],$j$[{"type": "cards", "cat": "vocab", "sub": "أجزاء الجسم", "label": "بطاقات أجزاء الجسم"}, {"type": "stories", "q": ["My Body"]}, {"type": "activities", "q": ["حواسّي"]}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',90),
('wk-healthy-habits','body','العادات الصحية والنظافة','العادات الصحية والنظافة الشخصية','1f9fc',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['نظافة','غسل اليدين','أسنان','نوم','رياضة','ماء','صحة','استحمام']::text[],'نحافظ على صحتنا بعادات بسيطة نفعلها كل يوم.',$j$[{"h": "عادات كل يوم", "x": "نغسل أيدينا بالماء والصابون، ونفرّش أسناننا، وننام باكرًا، ونشرب الماء.", "t": 1, "ic": "1f9fc"}, {"h": "متى نغسل اليدين؟", "x": "نغسلهما قبل الأكل وبعده، وبعد دخول الحمّام، وبعد اللعب في الخارج. نفرك اليدين بالصابون مدة تقارب عشرين ثانية.", "t": 2, "ic": "1f9fc"}, {"h": "الأسنان", "x": "نفرّش أسناننا صباحًا ومساءً، ونقلل من الحلويات والمشروبات المحلاة التي تضر الأسنان.", "t": 2, "ic": "1f9b7"}, {"h": "النوم والحركة", "x": "يحتاج الأطفال في سن المدرسة إلى نحو تسع إلى اثنتي عشرة ساعة نوم يوميًا. ونتحرك ونلعب في الهواء الطلق لتقوى العضلات.", "t": 2, "ic": "x_sleep"}, {"h": "طعام متوازن", "x": "نأكل الخضروات والفواكه والحبوب والبروتين ونشرب الماء، ونقلل من السكريات. ونستحم بانتظام ونقصّ الأظافر ونبدّل ملابسنا النظيفة. وإذا شعرنا بتعب أو ألم نخبر الكبار.", "t": 3, "ic": "x_stetho"}]$j$::jsonb,$j$[{"h": "الصابون", "x": "الصابون مع فرك اليدين يزيل الأوساخ والجراثيم أفضل من الماء وحده.", "ic": "1f9fc", "t": 2}, {"h": "تفريش الأسنان", "x": "ننظف أسناننا مرتين في اليوم على الأقل لحمايتها من التسوس.", "ic": "1f9b7", "t": 1}, {"h": "الماء", "x": "جسمنا يحتاج إلى الماء ليعمل جيدًا، فنشربه على مدار اليوم.", "ic": "1f4a7", "t": 1}, {"h": "النوم", "x": "أثناء النوم يرتاح الجسم ويساعدنا النوم الكافي على التركيز في المدرسة.", "ic": "x_sleep", "t": 3}]$j$::jsonb,$j$[{"w": "نظافة", "m": "أن يكون الجسم والمكان خاليًا من الأوساخ", "t": 1}, {"w": "جراثيم", "m": "كائنات صغيرة جدًا لا نراها وقد تسبب المرض", "t": 3, "ic": "1f9a0"}, {"w": "تسوس", "m": "ضرر يصيب السن", "t": 3}, {"w": "متوازن", "m": "فيه أنواع مختلفة من الطعام بقدر مناسب", "t": 3}, {"w": "صحة", "m": "أن يكون الجسم قويًا وسليمًا", "t": 1}]$j$::jsonb,$j$[{"k": "match", "p": [["1f9fc", "صابون"], ["1f9b7", "أسنان"], ["x_sleep", "نوم"], ["1f4a7", "ماء"]], "ts": [1, 2, 3]}, {"k": "tf", "q": "نغسل أيدينا قبل الأكل.", "a": true, "ts": [1, 2, 3]}, {"k": "mc", "q": "متى نفرّش أسناننا؟", "o": ["صباحًا ومساءً", "مرة في الشهر", "لا نفرّشها"], "a": 0, "ts": [1, 2]}, {"k": "fill", "q": "نغسل أيدينا بالماء و___.", "o": ["الصابون", "الرمل", "الدهان"], "a": 0, "ts": [2, 3]}, {"k": "sort", "g": ["عادة صحية", "ليست صحية"], "i": [["غسل اليدين", 0, "1f9fc"], ["شرب الماء", 0, "1f4a7"], ["السهر الطويل", 1, "x_bed"], ["أكل الحلوى كثيرًا", 1, "1f36c"]], "ts": [2, 3]}, {"k": "mc", "q": "ما الذي يحميه تفريش الأسنان؟", "o": ["الأسنان من التسوس", "العين", "القدم"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "لماذا نشرب الماء؟", "o": ["يحتاجه الجسم ليعمل", "ليصبح أطول فورًا", "لا نحتاجه"], "a": 0, "ts": [1, 2]}]$j$::jsonb,array['wk-body-parts','wk-fruit-veg','wk-safety']::text[],$j$[{"type": "stories", "q": ["أسنانه"]}, {"type": "activities", "q": ["نظافتي"]}, {"type": "cards", "cat": "vocab", "sub": "أجزاء الجسم", "label": "بطاقات أجزاء الجسم"}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',100),
('wk-sun','space','الشمس','الشمس','2600',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['شمس','نجمة','ضوء','حرارة','شروق','غروب']::text[],'الشمس تعطينا الضوء والدفء، وبدونها لا تكون حياة على الأرض.',$j$[{"h": "ما الشمس؟", "x": "الشمس كرة كبيرة مضيئة في السماء. تعطينا الضوء في النهار والدفء.", "t": 1, "ic": "2600"}, {"h": "شروق وغروب", "x": "نرى الشمس تشرق في الصباح وتغرب في المساء، ثم يأتي الليل.", "t": 1, "ic": "x_sunrise"}, {"h": "الشمس نجمة", "x": "الشمس نجمة من النجوم، لكنها أقرب نجمة إلينا. وهي كرة هائلة من الغاز الحار المتوهج. وتبدو أكبر من النجوم الأخرى لأنها قريبة.", "t": 2, "ic": "2b50"}, {"h": "احترس!", "x": "لا ننظر إلى الشمس مباشرة لأنها تؤذي العين. ونحمي أنفسنا في الحر بالقبعة والظل والماء.", "t": 2, "ic": "x_sunglasses"}, {"h": "أرقام عن الشمس", "x": "تبعد الشمس عن الأرض نحو 150 مليون كيلومتر. وحجمها يتسع لأكثر من مليون كرة بحجم الأرض. ويصل ضوؤها إلى الأرض في نحو ثماني دقائق. وتدور الأرض حولها دورة كاملة في سنة.", "t": 3, "ic": "1f310"}]$j$::jsonb,$j$[{"h": "نجمة", "x": "الشمس نجمة، وهي أقرب النجوم إلينا.", "ic": "2b50", "t": 2}, {"h": "الضوء والدفء", "x": "الشمس هي مصدر ضوء الأرض الرئيسي وحرارتها.", "ic": "2600", "t": 1}, {"h": "ثماني دقائق", "x": "يحتاج ضوء الشمس إلى نحو ثماني دقائق ليصل إلينا.", "ic": "23f3", "t": 3}, {"h": "أكبر من الأرض", "x": "حجم الشمس أكبر من حجم الأرض بأكثر من مليون مرة.", "ic": "x_earth", "t": 3}]$j$::jsonb,$j$[{"w": "نجمة", "m": "جسم كبير مضيء في الفضاء", "t": 1, "ic": "2b50"}, {"w": "مصدر ضوء", "m": "شيء يصدر الضوء بنفسه", "t": 2}, {"w": "شروق", "m": "ظهور الشمس في الصباح", "t": 1, "ic": "x_sunrise"}, {"w": "غروب", "m": "اختفاء الشمس في المساء", "t": 1}, {"w": "مدار", "m": "الطريق الذي يدور فيه جسم حول جسم آخر", "t": 3}]$j$::jsonb,$j$[{"k": "mc", "q": "ماذا تعطينا الشمس؟", "o": ["ضوءًا ودفئًا", "ثلجًا", "مطرًا فقط"], "a": 0, "ts": [1, 2]}, {"k": "tf", "q": "نحدّق إلى الشمس مباشرة.", "a": false, "ts": [1, 2, 3]}, {"k": "mc", "q": "الشمس هي...", "o": ["نجمة", "كوكب", "قمر"], "a": 0, "ts": [2, 3]}, {"k": "fill", "q": "تشرق الشمس في ___.", "o": ["الصباح", "منتصف الليل", "الشتاء فقط"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "كم يستغرق ضوء الشمس ليصل إلى الأرض؟", "o": ["نحو ثماني دقائق", "ثانية", "يوم كامل"], "a": 0, "ts": [3]}, {"k": "odd", "i": [["شمس", "2600"], ["مصباح", "i_lamp"], ["كرسي", "i_chair"]], "a": 2, "why": "الشمس والمصباح يصدران الضوء، أما الكرسي فلا.", "ts": [2, 3]}]$j$::jsonb,array['wk-day-night','wk-planets','wk-light-shadow']::text[],$j$[{"type": "stories", "q": ["الطيّار", "القمر"]}, {"type": "media", "q": ["الشمس"]}, {"type": "activities", "q": ["الطقس"]}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',110),
('wk-moon','space','القمر','القمر','1f319',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['قمر','هلال','بدر','أطوار القمر','فضاء','رواد']::text[],'القمر يدور حول الأرض، ونراه في السماء في الليل وأحيانًا في النهار.',$j$[{"h": "ما القمر؟", "x": "القمر جسم كبير يدور حول الأرض. نراه في الليل في السماء.", "t": 1, "ic": "1f319"}, {"h": "أشكال القمر", "x": "يبدو القمر هلالًا صغيرًا أحيانًا، وكاملًا مستديرًا أحيانًا، وتسمّى هذه الأشكال أطوار القمر.", "t": 1, "ic": "x_fullmoon"}, {"h": "هل للقمر ضوء؟", "x": "ليس للقمر ضوء خاص به. نراه مضيئًا لأن ضوء الشمس يسقط عليه فيعكسه إلينا. ويدور القمر حول الأرض دورة كاملة في نحو شهر.", "t": 2, "ic": "2600"}, {"h": "على سطح القمر", "x": "سطح القمر فيه حفر تسمى فوهات، وهو بلا هواء ولا ماء سائل، والجاذبية فيه أضعف من الأرض فيقفز الإنسان هناك عاليًا. وهبط أول إنسان على القمر عام 1969 في رحلة أبولو 11.", "t": 3, "ic": "x_astro"}, {"h": "لماذا تتغير الأطوار؟", "x": "يدور القمر حول الأرض، فنرى في كل ليلة جزءًا مختلفًا من نصفه المضيء بالشمس. وليس سبب الأطوار ظل الأرض.", "t": 3, "ic": "1f31b"}]$j$::jsonb,$j$[{"h": "بلا ضوء", "x": "القمر لا يصدر ضوءًا بنفسه، بل يعكس ضوء الشمس.", "ic": "1f319", "t": 2}, {"h": "أول هبوط", "x": "وصل أول البشر إلى القمر عام 1969 في رحلة أبولو 11.", "ic": "1f680", "t": 3}, {"h": "وجه واحد", "x": "نرى من الأرض الوجه نفسه للقمر دائمًا تقريبًا.", "ic": "x_fullmoon", "t": 3}, {"h": "دوران", "x": "يدور القمر حول الأرض في نحو شهر.", "ic": "1f319", "t": 2}]$j$::jsonb,$j$[{"w": "هلال", "m": "شكل القمر النحيل المقوّس", "t": 1, "ic": "1f319"}, {"w": "بدر", "m": "القمر الكامل المستدير", "t": 1, "ic": "x_fullmoon"}, {"w": "أطوار", "m": "أشكال القمر المتغيرة", "t": 2}, {"w": "فوهة", "m": "حفرة كبيرة على سطح القمر", "t": 3}, {"w": "جاذبية", "m": "قوة تشدّ الأشياء نحو الأرض أو القمر", "t": 3}]$j$::jsonb,$j$[{"k": "mc", "q": "أي جسم يدور حول الأرض؟", "o": ["القمر", "الشمس", "الشجرة"], "a": 0, "ts": [1, 2]}, {"k": "match", "p": [["1f319", "هلال"], ["x_fullmoon", "بدر"], ["2600", "شمس"], ["x_astro", "رائد فضاء"]], "ts": [1, 2, 3]}, {"k": "tf", "q": "القمر يضيء بنفسه.", "a": false, "ts": [2, 3]}, {"k": "fill", "q": "نرى القمر مضيئًا لأنه يعكس ضوء ___.", "o": ["الشمس", "المصباح", "النار"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "متى وصل أول إنسان إلى القمر؟", "o": ["عام 1969", "عام 1800", "عام 2020"], "a": 0, "ts": [3]}, {"k": "mc", "q": "ماذا نسمي أشكال القمر المختلفة؟", "o": ["الأطوار", "الفصول", "الأيام"], "a": 0, "ts": [3]}]$j$::jsonb,array['wk-sun','wk-day-night','wk-planets']::text[],$j$[{"type": "stories", "q": ["القمر"]}, {"type": "media", "q": ["القمر"]}, {"type": "activities", "q": ["الطقس"]}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',120),
('wk-day-night','space','الليل والنهار','الليل والنهار','x_night',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['ليل','نهار','دوران الأرض','شروق','غروب','ظل']::text[],'يتبدل الليل والنهار لأن الأرض تدور حول نفسها.',$j$[{"h": "نهار وليل", "x": "في النهار نرى الشمس ونلعب ونتعلم. وفي الليل نرى القمر والنجوم وننام.", "t": 1, "ic": "x_sunrise"}, {"h": "لماذا يأتي الليل؟", "x": "الأرض كرة تدور حول نفسها. الجهة التي تواجه الشمس يكون فيها نهار، والجهة الأخرى يكون فيها ليل.", "t": 2, "ic": "x_earth"}, {"h": "كم يستغرق الدوران؟", "x": "تدور الأرض حول نفسها دورة كاملة في نحو أربع وعشرين ساعة، وهذا هو اليوم.", "t": 2, "ic": "23f0"}, {"h": "الشمس لا تتحرك فعلًا", "x": "تبدو الشمس وكأنها تتحرك في السماء من الشرق إلى الغرب، لكن السبب هو دوران الأرض. ولهذا نرى الشمس تشرق من الشرق وتغرب في الغرب.", "t": 3, "ic": "2600"}, {"h": "الظل والوقت", "x": "يتغير طول ظلك خلال النهار: طويل في الصباح والمساء وقصير وقت الظهيرة. وفي بلدان مختلفة يكون الوقت مختلفًا في اللحظة نفسها.", "t": 3, "ic": "1f50d"}]$j$::jsonb,$j$[{"h": "أربع وعشرون ساعة", "x": "يستغرق اليوم الكامل نحو 24 ساعة.", "ic": "23f0", "t": 2}, {"h": "الأرض تدور", "x": "الأرض تدور حول نفسها ونحن لا نحس بذلك.", "ic": "x_earth", "t": 3}, {"h": "النجوم", "x": "نرى النجوم في الليل، وهي موجودة في النهار لكن ضوء الشمس يخفيها.", "ic": "2b50", "t": 2}, {"h": "الشروق", "x": "تشرق الشمس من جهة الشرق.", "ic": "x_sunrise", "t": 1}]$j$::jsonb,$j$[{"w": "شرق", "m": "الجهة التي تشرق منها الشمس", "t": 2}, {"w": "غرب", "m": "الجهة التي تغرب فيها الشمس", "t": 2}, {"w": "دوران", "m": "حركة الجسم حول نفسه", "t": 3}, {"w": "يوم", "m": "مدة دورة كاملة للأرض حول نفسها", "t": 2}, {"w": "ظل", "m": "منطقة معتمة خلف جسم يحجب الضوء", "t": 3}]$j$::jsonb,$j$[{"k": "sort", "g": ["أفعله في النهار", "أفعله في الليل"], "i": [["ألعب في الحديقة", 0, "1f3c3"], ["أذهب إلى المدرسة", 0, "i_bag"], ["أنام", 1, "x_sleep"], ["أرى النجوم", 1, "2b50"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "متى نرى النجوم؟", "o": ["في الليل", "وقت الظهر", "أثناء الغداء"], "a": 0, "ts": [1, 2]}, {"k": "tf", "q": "تدور الأرض حول نفسها.", "a": true, "ts": [2, 3]}, {"k": "fill", "q": "تشرق الشمس من جهة ___.", "o": ["الشرق", "الغرب", "الشمال"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "كم ساعة تقريبًا في اليوم؟", "o": ["24", "12", "60"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "لماذا تبدو الشمس وكأنها تتحرك؟", "o": ["لأن الأرض تدور", "لأنها تمشي", "لأن السحب تحملها"], "a": 0, "ts": [3]}]$j$::jsonb,array['wk-sun','wk-moon','wk-planets']::text[],$j$[{"type": "stories", "q": ["القمر"]}, {"type": "activities", "q": ["يومي"]}, {"type": "media", "q": ["اليوم", "الليل"]}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',130),
('wk-planets','space','المجموعة الشمسية والكواكب','المجموعة الشمسية والكواكب','x_saturn',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['كواكب','مجموعة شمسية','المشتري','زحل','المريخ','الأرض','الزهرة','عطارد','أورانوس','نبتون']::text[],'الأرض كوكب يدور حول الشمس مع كواكب أخرى.',$j$[{"h": "كوكبنا", "x": "نعيش على كوكب اسمه الأرض. هو كوكب جميل فيه ماء وهواء ونباتات وحيوانات.", "t": 1, "ic": "x_earth"}, {"h": "كواكب أخرى", "x": "حول الشمس تدور ثمانية كواكب، منها الأرض والمريخ وزحل.", "t": 1, "ic": "x_saturn"}, {"h": "ترتيب الكواكب", "x": "ترتيبها من الأقرب إلى الشمس: عطارد، الزهرة، الأرض، المريخ، المشتري، زحل، أورانوس، نبتون.", "t": 2, "ic": "1f310"}, {"h": "تعرّف عليها", "x": "المشتري أكبر الكواكب. وزحل له حلقات جميلة. والمريخ يسمّى الكوكب الأحمر. وعطارد أصغرها وأقربها إلى الشمس. والأرض هي الكوكب الوحيد الذي نعرف أن فيه حياة.", "t": 2, "ic": "1f52d"}, {"h": "المجموعة الشمسية", "x": "المجموعة الشمسية هي الشمس والكواكب وأقمارها وغيرها من الأجرام. تدور الكواكب حول الشمس في مسارات تسمّى مدارات. وتدور الأرض حول الشمس في سنة. وكوكب بلوتو يُصنَّف اليوم كوكبًا قزمًا.", "t": 3, "ic": "2b50"}]$j$::jsonb,$j$[{"h": "الأكبر", "x": "المشتري أكبر كواكب المجموعة الشمسية.", "ic": "1f310", "t": 2}, {"h": "الحلقات", "x": "لزحل حلقات واسعة تتكوّن من جليد وصخور.", "ic": "x_saturn", "t": 2}, {"h": "الأكثر حرارة", "x": "الزهرة أشد الكواكب حرارة، رغم أن عطارد أقرب إلى الشمس.", "ic": "2600", "t": 3}, {"h": "الأرض", "x": "الأرض هي الكوكب الوحيد المعروف الذي فيه حياة.", "ic": "x_earth", "t": 1}]$j$::jsonb,$j$[{"w": "كوكب", "m": "جسم كبير يدور حول نجم", "t": 1, "ic": "x_saturn"}, {"w": "مدار", "m": "مسار الكوكب حول الشمس", "t": 3}, {"w": "مجموعة شمسية", "m": "الشمس والكواكب التي تدور حولها", "t": 2}, {"w": "تلسكوب", "m": "جهاز يقرّب الأجسام البعيدة", "t": 2, "ic": "1f52d"}, {"w": "كوكب قزم", "m": "جسم أصغر من الكوكب مثل بلوتو", "t": 3}]$j$::jsonb,$j$[{"k": "mc", "q": "كم عدد كواكب المجموعة الشمسية؟", "o": ["ثمانية", "ثلاثة", "عشرون"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "أي كوكب نعيش عليه؟", "o": ["الأرض", "المريخ", "زحل"], "a": 0, "ts": [1, 2]}, {"k": "match", "p": [["x_earth", "الأرض"], ["x_saturn", "زحل"], ["2600", "الشمس"], ["1f319", "القمر"]], "ts": [1, 2, 3]}, {"k": "tf", "q": "الأرض أكبر كوكب في المجموعة الشمسية.", "a": false, "ts": [2, 3]}, {"k": "fill", "q": "يسمّى المريخ الكوكب ___.", "o": ["الأحمر", "الأزرق", "الأخضر"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "أي كوكب هو الأقرب إلى الشمس؟", "o": ["عطارد", "نبتون", "زحل"], "a": 0, "ts": [3]}, {"k": "mc", "q": "أي كوكب له حلقات واسعة مشهورة؟", "o": ["زحل", "الأرض", "عطارد"], "a": 0, "ts": [2, 3]}]$j$::jsonb,array['wk-sun','wk-moon','wk-day-night']::text[],$j$[{"type": "stories", "q": ["القمر", "الطيّار"]}, {"type": "media", "q": ["الكواكب", "الفضاء"]}, {"type": "cards", "cat": "vocab", "sub": "الطبيعة", "label": "بطاقات الطبيعة"}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',140),
('wk-water','science','الماء وحالاته','الماء وحالاته','1f4a7',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['ماء','ثلج','بخار','تبخر','تجمد','مطر','دورة الماء','سحاب']::text[],'الماء ضروري للحياة، وهو يظهر لنا بأشكال مختلفة.',$j$[{"h": "أين نجد الماء؟", "x": "نجد الماء في البحر والنهر والمطر ومن الصنبور. نشربه ونستحم به ونسقي به النباتات.", "t": 1, "ic": "1f4a7"}, {"h": "ثلاث حالات", "x": "الماء سائل نشربه. وهو ثلج صلب عندما يبرد كثيرًا. وهو بخار غير مرئي في الهواء عندما يسخن.", "t": 2, "ic": "x_ice"}, {"h": "درجات الحرارة", "x": "يتجمد الماء ويصبح ثلجًا عند درجة صفر مئوية، ويغلي ويتحول إلى بخار عند نحو مئة درجة مئوية عند مستوى سطح البحر.", "t": 3, "ic": "1f525"}, {"h": "دورة الماء", "x": "تسخّن الشمس ماء البحار فيتبخر، ويصعد البخار ويبرد فيتكاثف ويكوّن السحب، ثم ينزل مطرًا. ثم تجري المياه إلى الأنهار والبحار وتعود الدورة.", "t": 3, "ic": "1f327"}, {"h": "نوفّر الماء", "x": "الماء النظيف مهم وهو ليس كثيرًا في بعض الأماكن، لذلك نغلق الصنبور بعد الاستعمال وفي أثناء تفريش الأسنان، ولا نسرف.", "t": 1, "ic": "x_wcan"}]$j$::jsonb,$j$[{"h": "بحار وأنهار", "x": "نحو 71% من سطح الأرض مغطى بالماء.", "ic": "1f310", "t": 3}, {"h": "الثلج يطفو", "x": "الثلج يطفو على الماء لأنه أخف منه.", "ic": "x_ice", "t": 3}, {"h": "المطر", "x": "المطر ماء يسقط من السحب إلى الأرض.", "ic": "1f327", "t": 1}, {"h": "الأجسام", "x": "جسم الإنسان يحتوي على كمية كبيرة من الماء.", "ic": "1f4a7", "t": 2}]$j$::jsonb,$j$[{"w": "تبخر", "m": "تحول الماء إلى بخار بالحرارة", "t": 3}, {"w": "تجمد", "m": "تحول الماء إلى ثلج بالبرودة", "t": 3}, {"w": "تكاثف", "m": "تحول البخار إلى قطرات ماء", "t": 3}, {"w": "سائل", "m": "مادة تجري مثل الماء", "t": 2}, {"w": "صلب", "m": "مادة تحتفظ بشكلها مثل الثلج", "t": 2}]$j$::jsonb,$j$[{"k": "match", "p": [["1f4a7", "ماء"], ["x_ice", "ثلج"], ["1f327", "مطر"], ["2601", "سحابة"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "ماذا يصبح الماء عندما يبرد كثيرًا؟", "o": ["ثلجًا", "رملًا", "ورقًا"], "a": 0, "ts": [1, 2]}, {"k": "tf", "q": "نوفّر الماء ولا نسرف.", "a": true, "ts": [1, 2, 3]}, {"k": "fill", "q": "يتحول الماء إلى بخار عندما ___.", "o": ["يسخن", "يبرد", "ينام"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "عند أي درجة يتجمد الماء؟", "o": ["صفر مئوية", "50 مئوية", "100 مئوية"], "a": 0, "ts": [3]}, {"k": "sort", "g": ["ماء سائل", "ماء صلب"], "i": [["الماء في الكأس", 0, "1f4a7"], ["ماء النهر", 0, "x_water"], ["مكعب الثلج", 1, "x_ice"]], "ts": [2, 3]}, {"k": "mc", "q": "كيف تتكوّن السحب؟", "o": ["بخار الماء يبرد ويتكاثف", "من الرمل", "من الورق"], "a": 0, "ts": [3]}]$j$::jsonb,array['wk-air','wk-weather-seasons','wk-plant-needs']::text[],$j$[{"type": "stories", "q": ["قطرةِ الماء"]}, {"type": "activities", "q": ["يطفو", "الطقس"]}, {"type": "media", "q": ["الماء"]}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',150),
('wk-air','science','الهواء','الهواء','x_wind',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['هواء','رياح','أكسجين','تنفس','بالون','تلوث']::text[],'الهواء حولنا في كل مكان، لا نراه لكننا نحس به.',$j$[{"h": "الهواء حولنا", "x": "لا نرى الهواء لكننا نحس به عندما يتحرك. الهواء المتحرك يسمى رياحًا.", "t": 1, "ic": "1f4a8"}, {"h": "نحتاج إليه", "x": "نتنفس الهواء لنعيش. وتحتاجه الحيوانات والنباتات أيضًا.", "t": 1, "ic": "1f9e0"}, {"h": "الهواء يشغل مكانًا", "x": "عندما ننفخ بالونًا ينتفخ لأن الهواء يملؤه ويشغل مكانًا. والهواء له وزن ولو كان قليلًا.", "t": 2, "ic": "i_balloon"}, {"h": "مم يتكوّن؟", "x": "يتكوّن الهواء من عدة غازات، أكثرها النيتروجين (نحو 78%)، ثم الأكسجين (نحو 21%) الذي نتنفسه، وغازات أخرى بنسب قليلة.", "t": 3, "ic": "1f52c"}, {"h": "هواء نظيف", "x": "قد يتلوث الهواء بالدخان وعوادم السيارات. نحافظ عليه بزراعة الأشجار واستعمال وسائل نقل نظيفة وعدم حرق النفايات.", "t": 3, "ic": "1f333"}]$j$::jsonb,$j$[{"h": "الأكسجين", "x": "نحو 21% من الهواء أكسجين نتنفسه.", "ic": "x_wind", "t": 3}, {"h": "الرياح", "x": "الرياح هواء يتحرك، وتحرّك الطائرات الورقية وتسيّر السفن الشراعية.", "ic": "1fa81", "t": 1}, {"h": "طيران", "x": "تطير الطائرات في الهواء بفضل أجنحتها وقوة محركاتها.", "ic": "2708", "t": 2}, {"h": "النباتات", "x": "النباتات تضيف الأكسجين إلى الهواء.", "ic": "1f333", "t": 2}]$j$::jsonb,$j$[{"w": "رياح", "m": "هواء يتحرك", "t": 1}, {"w": "أكسجين", "m": "غاز في الهواء نتنفسه", "t": 2}, {"w": "تلوث", "m": "وجود مواد ضارة في الهواء أو الماء", "t": 3}, {"w": "غاز", "m": "مادة لا شكل لها مثل الهواء", "t": 3}, {"w": "تنفس", "m": "إدخال الهواء إلى الرئتين وإخراجه", "t": 1}]$j$::jsonb,$j$[{"k": "mc", "q": "ما اسم الهواء المتحرك؟", "o": ["رياح", "ثلج", "غبار"], "a": 0, "ts": [1, 2]}, {"k": "tf", "q": "نستطيع أن نرى الهواء.", "a": false, "ts": [1, 2, 3]}, {"k": "match", "p": [["i_balloon", "بالون"], ["1fa81", "طائرة ورقية"], ["x_wind", "رياح"], ["2708", "طائرة"]], "ts": [1, 2, 3]}, {"k": "fill", "q": "نتنفس ___.", "o": ["الهواء", "الحجارة", "الصابون"], "a": 0, "ts": [1, 2]}, {"k": "mc", "q": "أي غاز في الهواء نحتاجه لنتنفس؟", "o": ["الأكسجين", "الدخان", "الغبار"], "a": 0, "ts": [3]}, {"k": "sort", "g": ["يتحرك بالهواء", "لا يتحرك بالهواء"], "i": [["الطائرة الورقية", 0, "1fa81"], ["البالون", 0, "i_balloon"], ["الحجر", 1, "x_stone"]], "ts": [2, 3]}]$j$::jsonb,array['wk-water','wk-sound','wk-weather-seasons']::text[],$j$[{"type": "activities", "q": ["يطفو"]}, {"type": "media", "q": ["الهواء"]}, {"type": "cards", "cat": "vocab", "sub": "الطبيعة", "label": "بطاقات الطبيعة"}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',160),
('wk-light-shadow','science','الضوء والظل','الضوء والظل','1f4a1',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['ضوء','ظل','مصباح','قوس قزح','انعكاس','مرآة']::text[],'الضوء يساعدنا على الرؤية، وعندما يحجبه جسم يتكوّن ظل.',$j$[{"h": "مصادر الضوء", "x": "الشمس والمصباح والنار والمصباح اليدوي تعطي ضوءًا.", "t": 1, "ic": "1f4a1"}, {"h": "ما الظل؟", "x": "عندما يقف جسم في طريق الضوء يتكوّن خلفه ظل. نرى ظلنا في الشمس.", "t": 1, "ic": "1f441"}, {"h": "الظل يتغير", "x": "يكون ظلك طويلًا في الصباح الباكر والمساء، وقصيرًا وقت الظهيرة، لأن موقع الشمس يتغير. وكلما اقترب الجسم من المصباح كبر ظله.", "t": 2, "ic": "2600"}, {"h": "أنواع المواد", "x": "مواد شفافة كالزجاج النظيف تسمح بمرور الضوء كله. ومواد معتمة كالخشب لا تسمح به فتصنع ظلًا واضحًا. ومواد شبه شفافة كالورق الشفاف تسمح بمرور بعضه.", "t": 3, "ic": "1f50d"}, {"h": "قوس قزح", "x": "ضوء الشمس يبدو أبيض لكنه يتكوّن من ألوان عدة. عندما يمر في قطرات المطر يتفرق إلى ألوان فنرى قوس قزح.", "t": 3, "ic": "1f308"}]$j$::jsonb,$j$[{"h": "سرعة الضوء", "x": "الضوء أسرع شيء عرفه الإنسان؛ ويصل ضوء الشمس إلينا في دقائق معدودة.", "ic": "23f3", "t": 3}, {"h": "قوس قزح", "x": "قوس قزح يظهر عندما تتفرق ألوان الضوء في قطرات الماء.", "ic": "1f308", "t": 2}, {"h": "الظل", "x": "لا يتكوّن ظل إذا لم يكن هناك ضوء.", "ic": "1f441", "t": 2}, {"h": "أشعة الشمس", "x": "تمرّ أشعة الشمس في خطوط مستقيمة.", "ic": "2600", "t": 3}]$j$::jsonb,$j$[{"w": "مصدر ضوء", "m": "شيء يصدر الضوء", "t": 1}, {"w": "ظل", "m": "منطقة معتمة خلف جسم يحجب الضوء", "t": 1}, {"w": "شفاف", "m": "يسمح بمرور الضوء كله", "t": 3}, {"w": "معتم", "m": "لا يسمح بمرور الضوء", "t": 3}, {"w": "انعكاس", "m": "ارتداد الضوء عن سطح لامع", "t": 3}]$j$::jsonb,$j$[{"k": "mc", "q": "أي شيء يعطي ضوءًا؟", "o": ["الشمس", "الحجر", "الكرسي"], "a": 0, "ts": [1, 2]}, {"k": "odd", "i": [["شمس", "2600"], ["مصباح", "i_lamp"], ["حجر", "x_stone"]], "a": 2, "why": "الحجر لا يصدر ضوءًا.", "ts": [1, 2, 3]}, {"k": "tf", "q": "يتكوّن الظل عندما يحجب جسم الضوء.", "a": true, "ts": [1, 2, 3]}, {"k": "fill", "q": "يكون الظل ___ وقت الظهيرة.", "o": ["قصيرًا", "طويلًا جدًا", "بلا لون"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "أي مادة تسمح بمرور الضوء؟", "o": ["الزجاج الشفاف", "الخشب", "الحجر"], "a": 0, "ts": [3]}, {"k": "mc", "q": "متى يظهر قوس قزح؟", "o": ["عندما يمر ضوء الشمس بقطرات الماء", "في الظلام", "مع الثلج فقط"], "a": 0, "ts": [3]}]$j$::jsonb,array['wk-sun','wk-day-night','wk-senses']::text[],$j$[{"type": "media", "q": ["الضوء", "الظل"]}, {"type": "activities", "q": ["يطفو", "الطقس"]}, {"type": "stories", "q": ["القمر"]}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',170),
('wk-sound','science','الصوت','الصوت','i_sound',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['صوت','اهتزاز','أذن','طبل','موسيقى','ضجيج','ارتفاع الصوت']::text[],'نسمع الأصوات كل يوم، فكيف يصنع الصوت؟',$j$[{"h": "أصوات حولنا", "x": "نسمع صوت الجرس والطبل وبكاء الطفل وصوت الطيور.", "t": 1, "ic": "i_bell"}, {"h": "ما سبب الصوت؟", "x": "يصدر الصوت عندما يهتز الشيء. إذا لمست طبلًا وهو يُقرع فستحسّ بالاهتزاز في يدك.", "t": 2, "ic": "1f941"}, {"h": "كيف يصل إلينا؟", "x": "ينتقل الصوت في الهواء حتى يصل إلى أذننا. وينتقل أيضًا في الماء وفي المواد الصلبة. ولا ينتقل في الفضاء لأنه لا هواء فيه.", "t": 3, "ic": "x_ear"}, {"h": "قوي وضعيف", "x": "الصوت قد يكون عاليًا أو منخفضًا، وحادًا أو غليظًا. الآلات الموسيقية تصدر أصواتًا متنوعة بالاهتزاز.", "t": 2, "ic": "1f3ba"}, {"h": "نحمي آذاننا", "x": "الأصوات العالية جدًا تضر السمع، لذلك لا نرفع صوت السماعات ونبتعد عن الضجيج الشديد.", "t": 3, "ic": "x_ear"}]$j$::jsonb,$j$[{"h": "في الماء", "x": "ينتقل الصوت في الماء أسرع من انتقاله في الهواء.", "ic": "1f4a7", "t": 3}, {"h": "في الفضاء", "x": "لا نسمع صوتًا في الفضاء لأنه لا يوجد هواء ينقله.", "ic": "1f680", "t": 3}, {"h": "الاهتزاز", "x": "عندما تحدّث، يهتز الحبلان الصوتيان في حنجرتك.", "ic": "1f5e3", "t": 2}, {"h": "الطبل", "x": "عندما تقرع الطبل يهتز جلده فيصدر صوتًا.", "ic": "1f941", "t": 1}]$j$::jsonb,$j$[{"w": "اهتزاز", "m": "حركة سريعة ذهابًا وإيابًا", "t": 2}, {"w": "صدى", "m": "صوت يرتد عن سطح فيُسمع من جديد", "t": 3}, {"w": "عالٍ", "m": "صوت قوي", "t": 1}, {"w": "منخفض", "m": "صوت ضعيف", "t": 1}, {"w": "ضجيج", "m": "أصوات عالية مزعجة", "t": 2}]$j$::jsonb,$j$[{"k": "mc", "q": "بماذا نسمع الصوت؟", "o": ["بالأذن", "بالعين", "بالقدم"], "a": 0, "ts": [1, 2]}, {"k": "match", "p": [["1f941", "طبل"], ["1f3ba", "بوق"], ["i_bell", "جرس"], ["x_ear", "أذن"]], "ts": [1, 2, 3]}, {"k": "tf", "q": "يصدر الصوت عندما يهتز الشيء.", "a": true, "ts": [2, 3]}, {"k": "fill", "q": "ينتقل الصوت في ___.", "o": ["الهواء", "الفراغ فقط", "الظلام فقط"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "لماذا لا نسمع صوتًا في الفضاء؟", "o": ["لأنه لا يوجد هواء ينقله", "لأنه بعيد جدًا", "لأن الأذن لا تعمل"], "a": 0, "ts": [3]}, {"k": "sort", "g": ["صوت عالٍ", "صوت هادئ"], "i": [["الرعد", 0, "26c8"], ["الطبل القوي", 0, "1f941"], ["همس الطفل", 1, "1f5e3"]], "ts": [2, 3]}]$j$::jsonb,array['wk-senses','wk-air']::text[],$j$[{"type": "media", "q": ["الصوت"]}, {"type": "activities", "q": ["حواسّي"]}, {"type": "cards", "cat": "vocab", "sub": "أجزاء الجسم", "label": "بطاقات أجزاء الجسم"}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',180),
('wk-continents-oceans','geo','القارات والمحيطات','القارات والمحيطات','1f310',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['قارات','محيطات','آسيا','أفريقيا','أوروبا','أمريكا','أستراليا','أنتاركتيكا','عُمان','خريطة']::text[],'سطح الأرض فيه يابسة وماء، واليابسة الكبيرة نسميها قارات.',$j$[{"h": "الأرض كرة", "x": "الأرض شكلها كرة. وعليها ماء كثير وعليها يابسة.", "t": 1, "ic": "x_earth"}, {"h": "القارات", "x": "في العالم سبع قارات: آسيا وأفريقيا وأوروبا وأمريكا الشمالية وأمريكا الجنوبية وأستراليا وأنتاركتيكا (القارة القطبية الجنوبية).", "t": 2, "ic": "1f5fa"}, {"h": "المحيطات", "x": "في العالم خمسة محيطات: الهادئ والأطلسي والهندي والجنوبي والمتجمد الشمالي. وأكبرها الهادئ.", "t": 2, "ic": "x_water"}, {"h": "أين نحن؟", "x": "تقع سلطنة عُمان في قارة آسيا، في جنوب شرق شبه الجزيرة العربية، وتطل على بحر العرب وخليج عُمان.", "t": 2, "ic": "x_flag"}, {"h": "أرقام وحقائق", "x": "آسيا أكبر القارات، وأستراليا أصغرها، وأنتاركتيكا أبردها وتغطيها الثلوج. والمحيط الهادئ أكبر وأعمق المحيطات. ونستعمل الخرائط والكرة الأرضية لنعرف أماكن القارات والمحيطات.", "t": 3, "ic": "i_globe"}]$j$::jsonb,$j$[{"h": "سبع قارات", "x": "تتكوّن يابسة العالم من سبع قارات.", "ic": "1f5fa", "t": 2}, {"h": "المحيط الهادئ", "x": "المحيط الهادئ أكبر محيطات العالم.", "ic": "x_water", "t": 3}, {"h": "أنتاركتيكا", "x": "أنتاركتيكا أبرد قارات العالم وتغطيها الثلوج.", "ic": "x_ice", "t": 3}, {"h": "مجاورون", "x": "تُطل عُمان على بحر العرب وهو جزء من المحيط الهندي.", "ic": "x_flag", "t": 3}]$j$::jsonb,$j$[{"w": "قارة", "m": "قطعة كبيرة جدًا من اليابسة", "t": 2}, {"w": "محيط", "m": "مساحة ماء مالح واسعة", "t": 2}, {"w": "خريطة", "m": "رسم يوضح أماكن الأشياء على الأرض", "t": 1, "ic": "1f5fa"}, {"w": "كرة أرضية", "m": "نموذج دائري للأرض", "t": 2, "ic": "i_globe"}, {"w": "يابسة", "m": "الأرض غير المغطاة بالماء", "t": 1}]$j$::jsonb,$j$[{"k": "mc", "q": "كم عدد قارات العالم؟", "o": ["سبع", "ثلاث", "عشر"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "في أي قارة تقع سلطنة عُمان؟", "o": ["آسيا", "أوروبا", "أستراليا"], "a": 0, "ts": [2, 3]}, {"k": "tf", "q": "على الأرض ماء ويابسة.", "a": true, "ts": [1, 2, 3]}, {"k": "fill", "q": "أكبر المحيطات هو المحيط ___.", "o": ["الهادئ", "المتجمد", "الأحمر"], "a": 0, "ts": [3]}, {"k": "match", "p": [["x_earth", "الأرض"], ["1f5fa", "خريطة"], ["x_flag", "علم"], ["x_water", "ماء"]], "ts": [1, 2]}, {"k": "mc", "q": "أي قارة هي الأكبر؟", "o": ["آسيا", "أستراليا", "أنتاركتيكا"], "a": 0, "ts": [3]}]$j$::jsonb,array['wk-deserts-forests','wk-weather-seasons','wk-sea']::text[],$j$[{"type": "media", "q": ["الخريطة", "الأرض"]}, {"type": "activities", "q": ["الطقس"]}, {"type": "cards", "cat": "vocab", "sub": "الأماكن", "label": "بطاقات الأماكن"}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',190),
('wk-weather-seasons','geo','الطقس والفصول','الطقس والفصول','1f327',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['طقس','مطر','رياح','فصول','صيف','شتاء','خريف','ربيع','ظفار','مناخ']::text[],'الطقس يتغير من يوم إلى يوم، وله أشكال كثيرة.',$j$[{"h": "أنواع الطقس", "x": "الطقس قد يكون مشمسًا أو غائمًا أو ماطرًا أو عاصفًا أو باردًا أو حارًا.", "t": 1, "ic": "2601"}, {"h": "ماذا نلبس؟", "x": "في الطقس الحار نلبس ملابس خفيفة ونحمل الماء ونضع القبعة. وفي الشتاء البارد نلبس معطفًا ثقيلًا. وفي المطر نحمل المظلة.", "t": 1, "ic": "x_umbrella"}, {"h": "كيف نعرف الطقس؟", "x": "نستعمل المحرار (الترمومتر) لقياس درجة الحرارة. ونتابع نشرة الطقس لنعرف هل سيكون الجو مناسبًا للّعب في الخارج.", "t": 2, "ic": "1f4cf"}, {"h": "الفصول", "x": "في كثير من أنحاء العالم أربعة فصول: الربيع والصيف والخريف والشتاء. وتتغير الفصول لأن الأرض تميل وهي تدور حول الشمس في سنة.", "t": 3, "ic": "2600"}, {"h": "الطقس والمناخ", "x": "الطقس هو حال الجو اليوم. أما المناخ فهو الطقس المعتاد في منطقة خلال سنوات طويلة. وفي سلطنة عُمان صيف حار في أغلب المناطق، وفي محافظة ظفار موسم الخريف الذي يتميز بالرذاذ والأجواء المعتدلة في الصيف.", "t": 3, "ic": "x_flag"}]$j$::jsonb,$j$[{"h": "قوس قزح", "x": "يظهر قوس قزح عندما يلتقي المطر بضوء الشمس.", "ic": "1f308", "t": 1}, {"h": "الرعد", "x": "نرى البرق قبل أن نسمع الرعد لأن الضوء أسرع من الصوت.", "ic": "26c8", "t": 3}, {"h": "ظفار", "x": "يشهد جنوب سلطنة عُمان في فصل الصيف موسم الخريف الذي يتميز بالرذاذ والأجواء المعتدلة.", "ic": "x_flag", "t": 3}, {"h": "المحرار", "x": "نقيس درجة الحرارة بجهاز اسمه المحرار.", "ic": "1f4cf", "t": 2}]$j$::jsonb,$j$[{"w": "طقس", "m": "حال الجو في وقت معين", "t": 1}, {"w": "مناخ", "m": "الطقس المعتاد في منطقة خلال سنوات", "t": 3}, {"w": "محرار", "m": "جهاز يقيس درجة الحرارة", "t": 2}, {"w": "عاصف", "m": "طقس فيه رياح شديدة", "t": 2}, {"w": "فصل", "m": "جزء من السنة له طقس معين", "t": 2}]$j$::jsonb,$j$[{"k": "match", "p": [["2600", "مشمس"], ["2601", "غائم"], ["1f327", "ماطر"], ["x_wind", "عاصف"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "ماذا نحمل في المطر؟", "o": ["مظلة", "قبعة الشمس", "كرة"], "a": 0, "ts": [1, 2]}, {"k": "tf", "q": "نقيس درجة الحرارة بالمحرار.", "a": true, "ts": [2, 3]}, {"k": "fill", "q": "كم فصلًا في كثير من بلدان العالم؟ ___", "o": ["أربعة", "اثنان", "عشرة"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "ما الفرق بين الطقس والمناخ؟", "o": ["المناخ هو الطقس المعتاد خلال سنوات طويلة", "لا فرق", "الطقس خاص بالليل"], "a": 0, "ts": [3]}, {"k": "sort", "g": ["طقس حار", "طقس بارد"], "i": [["نلبس قبعة شمس", 0, "x_sunhat"], ["نلبس قفازات", 1, "x_mittens"], ["نصنع رجل ثلج", 1, "x_snowman"], ["نشرب ماءً كثيرًا", 0, "x_water"]], "ts": [1, 2, 3]}]$j$::jsonb,array['wk-water','wk-continents-oceans','wk-deserts-forests']::text[],$j$[{"type": "activities", "q": ["الطقس"]}, {"type": "stories", "q": ["Weather"]}, {"type": "media", "q": ["الطقس"]}, {"type": "cards", "cat": "vocab", "sub": "الملابس", "label": "بطاقات الملابس"}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',200),
('wk-deserts-forests','geo','الصحاري والغابات','الصحاري والغابات','1f3dd',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['صحراء','غابة','جمل','واحة','نخيل','غابات مطيرة','كثبان']::text[],'من البيئات الطبيعية الصحراء والغابة، ولكل منهما نباتات وحيوانات تناسبها.',$j$[{"h": "الصحراء", "x": "الصحراء مكان قليل المطر فيها رمال وكثبان وصخور. وتعيش فيها حيوانات مثل الجمل.", "t": 1, "ic": "1f42a"}, {"h": "الغابة", "x": "الغابة مكان فيه أشجار كثيرة وحيوانات مختلفة تعيش بين الأشجار.", "t": 1, "ic": "1f333"}, {"h": "الجمل صديق الصحراء", "x": "للجمل سنام يخزّن فيه الدهون، وجفون وأهداب طويلة تحمي عينيه من الغبار، وخفّ واسع لا يغوص في الرمل. ويتحمل العطش مدة طويلة.", "t": 2, "ic": "1f42a"}, {"h": "الواحة", "x": "الواحة مكان في الصحراء فيه ماء، فتنمو فيه نخيل ونباتات ويعيش الناس.", "t": 2, "ic": "1f334"}, {"h": "فوائد الغابة", "x": "تعطينا الغابات الأكسجين والخشب وهي بيت لحيوانات كثيرة. وأكبر غابة مطيرة في العالم غابة الأمازون. ومن أكبر الصحاري الرملية في العالم الربع الخالي الذي يمتد في أراضي عدة دول منها سلطنة عُمان، والصحراء الكبرى في أفريقيا أكبر صحراء حارة.", "t": 3, "ic": "1f331"}]$j$::jsonb,$j$[{"h": "نهار حار وليل بارد", "x": "يكون الجو في كثير من الصحارى حارًا في النهار وباردًا في الليل.", "ic": "2600", "t": 2}, {"h": "الصحراء الكبرى", "x": "الصحراء الكبرى في أفريقيا أكبر صحراء حارة في العالم.", "ic": "1f3dd", "t": 3}, {"h": "الأمازون", "x": "غابة الأمازون أكبر غابة مطيرة في العالم.", "ic": "1f333", "t": 3}, {"h": "الربع الخالي", "x": "يمتد الربع الخالي في أراضي عدة دول منها سلطنة عُمان.", "ic": "1f3dd", "t": 3}]$j$::jsonb,$j$[{"w": "كثيب", "m": "تل من الرمل", "t": 2}, {"w": "واحة", "m": "مكان في الصحراء فيه ماء ونبات", "t": 2}, {"w": "غابة مطيرة", "m": "غابة كثيفة يهطل فيها مطر كثير", "t": 3}, {"w": "سنام", "m": "جزء على ظهر الجمل يخزن الدهون", "t": 2}, {"w": "بيئة", "m": "ما يحيط بالكائن الحي من ماء وهواء ونبات", "t": 3}]$j$::jsonb,$j$[{"k": "match", "p": [["1f42a", "جمل"], ["1f334", "نخلة"], ["1f333", "شجرة"], ["1f3dd", "صحراء"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "أي حيوان يعيش في الصحراء؟", "o": ["الجمل", "الحوت", "البطريق"], "a": 0, "ts": [1, 2]}, {"k": "tf", "q": "الغابة فيها أشجار كثيرة.", "a": true, "ts": [1, 2, 3]}, {"k": "sort", "g": ["صحراء", "غابة"], "i": [["الجمل", 0, "1f42a"], ["الكثبان", 0, "1f3dd"], ["القرد", 1, "1f435"], ["الأشجار الكثيفة", 1, "1f333"]], "ts": [2, 3]}, {"k": "fill", "q": "الواحة مكان في الصحراء فيه ___.", "o": ["ماء", "ثلج", "بحر"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "ما أكبر غابة مطيرة؟", "o": ["الأمازون", "الربع الخالي", "الصحراء الكبرى"], "a": 0, "ts": [3]}]$j$::jsonb,array['wk-wild','wk-continents-oceans','wk-weather-seasons']::text[],$j$[{"type": "stories", "q": ["الجمل", "الغابة"]}, {"type": "cards", "cat": "animals", "sub": "برية", "label": "بطاقات الحيوانات البرية"}, {"type": "media", "q": ["الصحراء"]}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',210),
('wk-jobs','culture','المهن','المهن في مجتمعي','x_doctor',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['مهن','طبيب','معلم','مزارع','شرطي','طباخ','طيار','بنّاء','إطفائي','وظائف']::text[],'يعمل الناس في مهن مختلفة ليخدموا بعضهم.',$j$[{"h": "من هم؟", "x": "الطبيب يعالج المرضى. والمعلم يعلّم الأطفال. والمزارع يزرع الطعام. والشرطي يحمي الناس.", "t": 1, "ic": "x_doctor"}, {"h": "مهن أخرى", "x": "الطباخ يطبخ الطعام. والإطفائي يطفئ الحريق. والطيار يقود الطائرة. والبنّاء يبني البيوت.", "t": 1, "ic": "x_chef"}, {"h": "أدوات كل مهنة", "x": "لكل مهنة أدوات: السماعة الطبية للطبيب، والسبورة والقلم للمعلم، والمحراث والمعول للمزارع، والمطرقة للبنّاء.", "t": 2, "ic": "x_hammer"}, {"h": "نتعاون معًا", "x": "نحتاج إلى كل المهن، فلا يستطيع شخص واحد أن يفعل كل شيء. لذلك نحترم كل من يعمل بجدّ.", "t": 2, "ic": "1f44f"}, {"h": "لماذا يعمل الناس؟", "x": "يعمل الناس ليخدموا مجتمعهم وليحصلوا على راتب يشترون به حاجاتهم. ولكل مهنة علم ومهارات يتعلمها الإنسان في المدرسة والجامعة أو التدريب. وما تتعلمه اليوم يساعدك لتختار مهنة تحبها غدًا.", "t": 3, "ic": "i_cap"}]$j$::jsonb,$j$[{"h": "طبيب", "x": "يستعمل الطبيب السماعة ليسمع نبض القلب.", "ic": "x_stetho", "t": 1}, {"h": "إطفائي", "x": "يرتدي الإطفائي ملابس خاصة تحميه من النار والحرارة.", "ic": "x_firefighter", "t": 2}, {"h": "طيار", "x": "يتدرب الطيار سنوات طويلة قبل أن يقود الطائرة.", "ic": "x_pilot", "t": 3}, {"h": "تعاون", "x": "كثير من المهن تعمل معًا، مثل الطبيب والممرض في المستشفى.", "ic": "1f44f", "t": 3}]$j$::jsonb,$j$[{"w": "مهنة", "m": "عمل يقوم به الإنسان", "t": 1}, {"w": "خدمة", "m": "مساعدة الناس", "t": 2}, {"w": "أدوات", "m": "أشياء نستعملها في العمل", "t": 1}, {"w": "راتب", "m": "مال يأخذه العامل مقابل عمله", "t": 3}, {"w": "تدريب", "m": "تعلّم مهارات العمل", "t": 3}]$j$::jsonb,$j$[{"k": "match", "p": [["x_doctor", "طبيب"], ["x_teacher", "معلم"], ["x_farmer", "مزارع"], ["x_firefighter", "إطفائي"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "من يعالج المرضى؟", "o": ["الطبيب", "الطيار", "الطباخ"], "a": 0, "ts": [1, 2]}, {"k": "mc", "q": "من يطفئ الحريق؟", "o": ["الإطفائي", "المعلم", "المزارع"], "a": 0, "ts": [1, 2]}, {"k": "match", "p": [["x_stetho", "سماعة"], ["x_hammer", "مطرقة"], ["x_board", "سبورة"], ["x_pot", "قدر"]], "ts": [2, 3]}, {"k": "tf", "q": "نحتاج إلى كل المهن ونحترم من يعمل.", "a": true, "ts": [2, 3]}, {"k": "fill", "q": "يقود ___ الطائرة.", "o": ["الطيار", "الطباخ", "المعلم"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "ماذا يستعمل المعلم في الصف؟", "o": ["السبورة والقلم", "المحراث", "المطرقة"], "a": 0, "ts": [2, 3]}]$j$::jsonb,array['wk-transport','wk-cooperation']::text[],$j$[{"type": "cards", "cat": "vocab", "sub": "المهن", "label": "بطاقات المهن"}, {"type": "media", "q": ["المهن"]}, {"type": "activities", "q": ["مسؤوليتي"]}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',220),
('wk-transport','culture','وسائل النقل','وسائل النقل','1f68c',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['سيارة','حافلة','قطار','طائرة','سفينة','دراجة','مواصلات','نقل']::text[],'نستعمل وسائل النقل لننتقل من مكان إلى آخر.',$j$[{"h": "في البر", "x": "نركب السيارة والحافلة والقطار. ونسير بالدراجة.", "t": 1, "ic": "1f697"}, {"h": "في البحر والجو", "x": "تسير السفينة في البحر. وتطير الطائرة في السماء.", "t": 1, "ic": "1f6a2"}, {"h": "لكل وسيلة طريقها", "x": "للسيارة والحافلة الطرق، وللقطار السكة الحديدية، وللسفينة البحر، وللطائرة المطار والسماء.", "t": 2, "ic": "1f682"}, {"h": "أمان في الطريق", "x": "نربط حزام الأمان في السيارة، ونعبر الشارع من الأماكن المخصصة ونحن ننظر يمينًا ويسارًا، وننتظر الإشارة الخضراء للمشاة.", "t": 2, "ic": "1f6b6"}, {"h": "لماذا تتنوع؟", "x": "تختلف الوسائل بحسب المسافة والحمولة. الحافلة والقطار ينقلان عددًا كبيرًا من الناس. والسفن تنقل بضائع كثيرة بين الدول. والطائرة أسرع في الرحلات البعيدة. وتعمل بعض السيارات بالكهرباء فتقلل الدخان.", "t": 3, "ic": "2708"}]$j$::jsonb,$j$[{"h": "القطار", "x": "يسير القطار على سكة حديدية وينقل ركابًا وبضائع.", "ic": "1f682", "t": 1}, {"h": "الدراجة", "x": "الدراجة وسيلة نقل نظيفة لا تُصدر دخانًا وهي مفيدة للصحة.", "ic": "1f6b2", "t": 2}, {"h": "الحزام", "x": "حزام الأمان يحميك في السيارة.", "ic": "1f697", "t": 2}, {"h": "الطائرة", "x": "الطائرة أسرع وسيلة لقطع المسافات البعيدة.", "ic": "2708", "t": 3}]$j$::jsonb,$j$[{"w": "مواصلات", "m": "وسائل ننتقل بها", "t": 1}, {"w": "مطار", "m": "مكان تقلع منه الطائرات وتهبط", "t": 2}, {"w": "ميناء", "m": "مكان ترسو فيه السفن", "t": 2}, {"w": "سكة", "m": "خطوط حديدية يسير عليها القطار", "t": 3}, {"w": "حمولة", "m": "ما تنقله وسيلة النقل", "t": 3}]$j$::jsonb,$j$[{"k": "match", "p": [["1f697", "سيارة"], ["1f682", "قطار"], ["1f6a2", "سفينة"], ["2708", "طائرة"]], "ts": [1, 2, 3]}, {"k": "sort", "g": ["في البر", "في الجو"], "i": [["الحافلة", 0, "1f68c"], ["الدراجة", 0, "1f6b2"], ["الطائرة", 1, "2708"], ["المروحية", 1, "1f681"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "أي وسيلة تسير في البحر؟", "o": ["السفينة", "القطار", "الدراجة"], "a": 0, "ts": [1, 2]}, {"k": "tf", "q": "نربط حزام الأمان في السيارة.", "a": true, "ts": [1, 2, 3]}, {"k": "fill", "q": "يسير القطار على ___.", "o": ["سكة حديدية", "الماء", "السحاب"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "أي وسيلة أنسب للرحلات البعيدة جدًا؟", "o": ["الطائرة", "الدراجة", "العربة"], "a": 0, "ts": [3]}]$j$::jsonb,array['wk-jobs','wk-safety']::text[],$j$[{"type": "cards", "cat": "vocab", "sub": "المواصلات", "label": "بطاقات المواصلات"}, {"type": "media", "q": ["المواصلات", "الطائرة"]}, {"type": "stories", "q": ["الطيّار"]}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',230),
('wk-cooperation','values','التعاون','التعاون','1f44f',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['تعاون','مشاركة','مساعدة','أصدقاء','عمل جماعي','فريق']::text[],'نتعاون عندما نعمل معًا لنصل إلى هدف واحد.',$j$[{"h": "ما التعاون؟", "x": "التعاون أن نساعد بعضنا. نرتب الغرفة معًا، ونحمل الأشياء الثقيلة معًا.", "t": 1, "ic": "1f44f"}, {"h": "أمثلة", "x": "أساعد أمي في ترتيب المائدة. وأشارك صديقي لعبتي. ونعمل معًا في الفصل لنرتب الكتب.", "t": 1, "ic": "i_blocks"}, {"h": "لماذا التعاون جميل؟", "x": "العمل مع الآخرين يجعل المهمة أسرع وأسهل، ويجعلنا نشعر بالسعادة. وكل شخص يقدم ما يحسنه.", "t": 2, "ic": "1f604"}, {"h": "كيف نتعاون؟", "x": "نستمع إلى رأي الآخرين، ونتبادل الأدوار، ونقول: هل أستطيع مساعدتك؟ ونشكر من ساعدنا.", "t": 2, "ic": "1f5e3"}, {"h": "الفريق", "x": "في الفريق لكل شخص دور. إذا تعاونا فنجاح الفريق نجاح لكل فرد فيه. وإذا اختلفنا نحاول أن نتحدث بهدوء ونتفق على حل مناسب.", "t": 3, "ic": "1f3c6"}]$j$::jsonb,$j$[{"h": "النمل", "x": "يتعاون النمل في حمل الطعام وبناء بيته.", "ic": "1f44f", "t": 2}, {"h": "أسهل معًا", "x": "حمل الشيء الثقيل بين شخصين أسهل من حمله وحدك.", "ic": "1f4aa", "t": 1}, {"h": "كلمات طيبة", "x": "عبارة «هل أستطيع مساعدتك؟» تبدأ بها التعاون.", "ic": "1f604", "t": 1}, {"h": "فريق", "x": "لاعبو الفريق يتعاونون ليحققوا هدفًا واحدًا.", "ic": "26bd", "t": 3}]$j$::jsonb,$j$[{"w": "تعاون", "m": "أن نعمل معًا", "t": 1}, {"w": "مشاركة", "m": "أن نعطي غيرنا جزءًا مما لدينا", "t": 1}, {"w": "فريق", "m": "مجموعة أشخاص يعملون لهدف واحد", "t": 2}, {"w": "دور", "m": "العمل الذي يقوم به كل شخص", "t": 3}, {"w": "احترام", "m": "معاملة الآخرين بلطف", "t": 2}]$j$::jsonb,$j$[{"k": "mc", "q": "ما معنى التعاون؟", "o": ["أن نعمل معًا ونساعد بعضنا", "أن نعمل وحدنا دائمًا", "أن نأخذ كل شيء"], "a": 0, "ts": [1, 2]}, {"k": "sort", "g": ["تعاون", "ليس تعاونًا"], "i": [["أساعد في ترتيب المائدة", 0, "1f37d"], ["أشارك لعبتي", 0, "1f9f8"], ["آخذ اللعبة من صديقي", 1, "1f620"]], "ts": [1, 2, 3]}, {"k": "tf", "q": "التعاون يجعل العمل أسهل.", "a": true, "ts": [1, 2, 3]}, {"k": "fill", "q": "أقول: هل أستطيع ___؟", "o": ["مساعدتك", "ضربك", "إزعاجك"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "ماذا نفعل في الفريق؟", "o": ["كل شخص يقوم بدوره", "واحد يعمل والباقي ينظر", "لا نتحدث"], "a": 0, "ts": [3]}]$j$::jsonb,array['wk-honesty','wk-jobs']::text[],$j$[{"type": "stories", "q": ["تتشارك", "الأصدقاء", "شكرًا"]}, {"type": "activities", "q": ["نرتّب"]}, {"type": "media", "q": ["التعاون"]}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',240),
('wk-honesty','values','الصدق','الصدق','1f604',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['صدق','أمانة','كذب','اعتراف بالخطأ','ثقة']::text[],'الصدق أن نقول الحقيقة وأن نفعل ما نقوله.',$j$[{"h": "ما الصدق؟", "x": "الصدق أن أقول الحقيقة. إذا كسرت شيئًا أقول للكبار ما حدث.", "t": 1, "ic": "1f604"}, {"h": "لماذا نصدق؟", "x": "عندما أصدق يثق بي أهلي وأصدقائي ويحبونني. والكذب يفقدنا الثقة.", "t": 1, "ic": "1f60a"}, {"h": "أعترف بالخطأ", "x": "كلنا نخطئ. من الشجاعة أن أقول: أخطأت، وأعتذر وأحاول إصلاح الخطأ. وهذا أفضل من أن أخفيه.", "t": 2, "ic": "1f4aa"}, {"h": "الأمانة", "x": "الأمانة قريبة من الصدق: أن أعيد ما أستعيره، وأن أحافظ على ما يُعطى لي، ولا آخذ ما ليس لي.", "t": 2, "ic": "1f511"}, {"h": "الثقة", "x": "إذا كنت صادقًا دائمًا فسيصدقك الناس حين تخبرهم بشيء مهم. أما إذا كذبت مرة، فقد يصعب أن يصدقك الناس بعدها. وأحيانًا يكون قول الحقيقة صعبًا لكنه الاختيار الصحيح.", "t": 3, "ic": "1f9e0"}]$j$::jsonb,$j$[{"h": "اعتراف", "x": "قول الحقيقة بعد الخطأ يحل المشكلة أسرع.", "ic": "1f604", "t": 1}, {"h": "ثقة", "x": "الصدق يبني الثقة بين الناس.", "ic": "1f60a", "t": 2}, {"h": "أمانة", "x": "إعادة ما نستعيره من أصدقائنا نوع من الأمانة.", "ic": "1f511", "t": 2}, {"h": "شجاعة", "x": "قول الحقيقة عندما نخطئ يحتاج إلى شجاعة.", "ic": "1f4aa", "t": 3}]$j$::jsonb,$j$[{"w": "صدق", "m": "قول الحقيقة", "t": 1}, {"w": "أمانة", "m": "المحافظة على ما يُعطى لنا وإعادته", "t": 2}, {"w": "اعتراف", "m": "قول ما حدث بصراحة", "t": 2}, {"w": "ثقة", "m": "أن يصدقك الناس ويعتمدوا عليك", "t": 3}, {"w": "اعتذار", "m": "أن نقول إننا آسفون", "t": 2}]$j$::jsonb,$j$[{"k": "mc", "q": "ماذا أفعل إذا كسرت شيئًا؟", "o": ["أقول الحقيقة للكبار", "أخفي الأمر", "أتهم غيري"], "a": 0, "ts": [1, 2]}, {"k": "tf", "q": "الصدق يجعل الناس يثقون بنا.", "a": true, "ts": [1, 2, 3]}, {"k": "sort", "g": ["صدق", "ليس صدقًا"], "i": [["أقول ما حدث", 0, "1f604"], ["أعيد الكتاب لصاحبه", 0, "i_book"], ["أخفي الخطأ", 1, "1f628"]], "ts": [1, 2, 3]}, {"k": "fill", "q": "أقول: أخطأت وأنا ___.", "o": ["آسف", "غاضب", "مشغول"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "لماذا يحتاج الاعتراف بالخطأ إلى شجاعة؟", "o": ["لأنه قد يكون صعبًا لكنه صحيح", "لأنه بلا فائدة", "لأنه ممنوع"], "a": 0, "ts": [3]}]$j$::jsonb,array['wk-cooperation','wk-safety']::text[],$j$[{"type": "stories", "q": ["الكعكة"]}, {"type": "media", "q": ["الصدق"]}, {"type": "activities", "q": ["مسؤوليتي"]}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',250),
('wk-safety','values','السلامة اليومية','السلامة اليومية','x_policecar',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],array['سلامة','أمان','طوارئ','حريق','عبور الشارع','كهرباء','غرباء']::text[],'نحمي أنفسنا وغيرنا عندما نتبع قواعد السلامة.',$j$[{"h": "في البيت", "x": "لا ألمس الأشياء الساخنة والمقصات الحادة. وأبتعد عن الأفياش الكهربائية. وألعب بعيدًا عن النار.", "t": 1, "ic": "x_policecar"}, {"h": "في الشارع", "x": "أمسك بيد الكبير وأعبر من الأماكن المخصصة. وأنظر يمينًا ويسارًا وأنتظر السيارات.", "t": 1, "ic": "1f6b6"}, {"h": "مع الغرباء", "x": "لا أذهب مع أي شخص لا أعرفه، ولا أعطيه معلوماتي. وأخبر أهلي أو معلمي إن طلب مني أحد شيئًا.", "t": 2, "ic": "x_police"}, {"h": "أرقام الطوارئ", "x": "نتعلم رقم الطوارئ الذي نتصل به عند الخطر. رقم الطوارئ في سلطنة عُمان هو 9999. ونتصل به عند الحاجة الحقيقية فقط، ونخبر الكبار فورًا.", "t": 2, "ic": "x_firefighter"}, {"h": "الحريق والماء", "x": "إذا رأيت دخانًا أو نارًا أبتعد فورًا وأخبر الكبار. ولا أسبح في الماء إلا مع شخص كبير. ونتعلم أين المخارج في بيتنا ومدرستنا.", "t": 3, "ic": "1f525"}]$j$::jsonb,$j$[{"h": "عند الحريق", "x": "عند الحريق نخرج من المكان بسرعة ونخبر الكبار.", "ic": "x_firefighter", "t": 2}, {"h": "نعبر بأمان", "x": "ننظر يمينًا ويسارًا قبل عبور الشارع.", "ic": "1f6b6", "t": 1}, {"h": "9999", "x": "رقم الطوارئ في سلطنة عُمان هو 9999.", "ic": "x_policecar", "t": 3}, {"h": "الحزام", "x": "حزام الأمان وكرسي الطفل يحميانك في السيارة.", "ic": "1f697", "t": 2}]$j$::jsonb,$j$[{"w": "سلامة", "m": "أن نكون في أمان", "t": 1}, {"w": "طوارئ", "m": "حالة خطر تحتاج مساعدة سريعة", "t": 2}, {"w": "إسعاف", "m": "مساعدة سريعة لمن يتأذى", "t": 2}, {"w": "مخرج", "m": "مكان نخرج منه", "t": 3}, {"w": "غريب", "m": "شخص لا نعرفه", "t": 2}]$j$::jsonb,$j$[{"k": "mc", "q": "كيف أعبر الشارع؟", "o": ["أنظر يمينًا ويسارًا وأعبر من مكان مخصص", "أجري بسرعة", "أغمض عيني"], "a": 0, "ts": [1, 2]}, {"k": "tf", "q": "ألمس الأشياء الساخنة.", "a": false, "ts": [1, 2, 3]}, {"k": "mc", "q": "ماذا أفعل إذا رأيت دخانًا أو نارًا؟", "o": ["أبتعد وأخبر الكبار", "أقترب لأرى", "ألعب بها"], "a": 0, "ts": [2, 3]}, {"k": "fill", "q": "رقم الطوارئ في عُمان هو ___.", "o": ["9999", "1", "123456"], "a": 0, "ts": [3]}, {"k": "sort", "g": ["آمن", "غير آمن"], "i": [["أمسك يد الكبير", 0, "1f590"], ["أربط الحزام", 0, "1f697"], ["ألعب بالنار", 1, "1f525"], ["أذهب مع غريب", 1, "1f628"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "هل أذهب مع شخص لا أعرفه؟", "o": ["لا، وأخبر أهلي", "نعم", "أحيانًا"], "a": 0, "ts": [2, 3]}]$j$::jsonb,array['wk-healthy-habits','wk-transport','wk-honesty']::text[],$j$[{"type": "activities", "q": ["أنظّم", "أرتّب"]}, {"type": "media", "q": ["السلامة"]}, {"type": "cards", "cat": "vocab", "sub": "المهن", "label": "بطاقات المهن"}]$j$::jsonb,'معلومات علمية وتعليمية عامة ومستقرة، كُتبت بصياغة أصلية من إعداد زاد ولم تُنسخ من كتاب أو موقع.','كُتب المحتوى برمجيًا وراجعته زاد مراجعة عامة، وتحقق من المعلومات المحلية (مثل رقم الطوارئ) من مصادر منشورة. لم يراجعه مختص علمي أو تربوي بعد.','published',260)
